function showSaveIssue(){let box=$('#save-issue');if(!persistenceIssue){box?.remove();return;}if(!box){box=document.createElement('aside');box.id='save-issue';box.className='save-issue';box.setAttribute('role','alert');$('.header').after(box);}box.innerHTML=`<span>${esc(persistenceIssue)}</span><div>${!loadBlocked?btn('重試儲存','retry-save','secondary'):btn('保留原檔','export-raw','secondary')}${btn('匯出備份','export-data','secondary')}</div>`;}
function canResume(){const s=db.session;return !!(s&&s.childId===activeChild()?.id&&!s.finishedAt&&s.index<s.queue.length);}
function dailyLedger(){const cid=activeChild()?.id;if(!cid)return {done:[],newWords:[],rewardKeys:[],bonus:false};db.dailyLedger=db.dailyLedger||{};const days=db.dailyLedger[cid]||(db.dailyLedger[cid]={}),key=today();for(const k of Object.keys(days).sort().slice(0,-90))delete days[k];return days[key]||(days[key]={done:[],newWords:[],rewardKeys:[],bonus:false});}
function newSession(queue,mode){return {id:uid('s'),childId:activeChild().id,queue,index:0,mode,startedAt:new Date().toISOString(),answer:'',selected:null,feedback:null,scored:0,played:false,audioStatus:'idle'};}
function storeCurrentSession(){db.savedSessions=db.savedSessions||{};if(db.session)db.savedSessions[db.session.childId]=db.session;}
function weakTypes(w){const latest=new Map();attemptsFor(w.id).filter(a=>!a.technical&&a.correct!==null&&(!a.assisted||a.correct===false)).forEach(a=>latest.set(a.type,a));return ['listenSpell','spell','sentence','cloze','missing','listenChoice','meaning'].filter(t=>latest.get(t)?.correct===false);}
function effectiveType(w,t){if(t==='study')return t;if(w.kind==='sentence')return 'sentence';if(t==='sentence'&&!w.example)return 'listenSpell';if(t==='meaning'&&!w.zh&&!MEDIA_CATALOG[norm(w.en)]&&!imageFor(w))return 'listenChoice';if(t==='cloze'&&(!w.example||!WQEducation.gap(w.example,w.en).valid))return w.zh?'spell':'listenSpell';return t;}
function prepareItem(it,w){if(['meaning','listenChoice'].includes(it.type)&&!it.options)it.options=choiceOptions(w);if(it.type==='missing'&&!it.missing)it.missing=missingData(w.en);return it;}
function termPosition(text,term){const a=String(text).toLowerCase(),b=String(term).toLowerCase();let i=a.indexOf(b);while(i>=0){if((i===0||!/[a-z]/i.test(a[i-1]))&&(i+b.length===a.length||!/[a-z]/i.test(a[i+b.length])))return i;i=a.indexOf(b,i+1);}return -1;}
function scoreSentence(answer,expected,target){const clean=s=>String(s).trim().replace(/[’]/g,"'").replace(/[“”]/g,'"').replace(/\s+/g,' ');const a=clean(answer),e=clean(expected);const tokens=s=>s.match(/[A-Za-z0-9]+(?:'[A-Za-z]+)*/g)||[],at=tokens(a),et=tokens(e);const lexical=at.map(norm).join(' ')===et.map(norm).join(' '),capitalization=lexical&&at.join(' ')===et.join(' '),punct=s=>(s.match(/[^\w\s']/g)||[]).join(''),punctuation=punct(a)===punct(e);const targetCorrect=kindOf(target)==='sentence'?lexical:termPosition(a,target)>=0;return {correct:lexical&&capitalization&&punctuation,lexical,capitalization,punctuation,targetCorrect};}
function awardAnswer(w,it){const ledger=dailyLedger(),key=norm(w.en)+'|'+it.type;if(ledger.rewardKeys.includes(key))return;ledger.rewardKeys.push(key);activeChild().stars++;}
function activateRange(id){const r=childRanges().find(x=>x.id===id);if(!r)return;if(canResume()&&!confirm('切換默書範圍會結束未完成的一輪。已答紀錄會保留，繼續？'))return;const old=structuredClone(db);if(v24Policy().rangeLocks[activeChild().id]&&v23ParentAllowed())v24Policy().rangeLocks[activeChild().id]=id;activeChild().activeRangeId=id;db.session=null;if(!save()){db=old;return;}toast('已設為今次默書。');render();}
function captureImportDraft(){if(skipImportCapture){skipImportCapture=false;return;}if(!$('#range-title'))return;syncDraftInputs();importDraft.title=$('#range-title').value;importDraft.date=$('#range-date').value;importDraft.raw=$('#raw-words').value;importDraft.confirmed=$('#confirm-import')?.checked||false;}
function restoreImportDraft(){if(!$('#range-title'))return;$('#range-title').value=importDraft.title;$('#range-date').value=importDraft.date;$('#raw-words').value=importDraft.raw;const confirmed=importDraft.confirmed;renderWordEditor();importDraft.confirmed=confirmed;$('#confirm-import').checked=confirmed;updateImportPhoto();}
function clearImportDraft(){cancelOCR();if(ocrPreviewUrl)URL.revokeObjectURL(ocrPreviewUrl);ocrPreviewUrl='';ocrSelectedFile=null;draftWords=[];importDraft={title:'英文默書',date:'',raw:'',confirmed:false,source:'upload',fileName:''};skipImportCapture=!!$('#range-title');}
function updateImportPhoto(){const img=$('#ocr-preview'),name=$('#ocr-file-name'),run=$('#run-ocr');if(!img)return;img.hidden=!ocrPreviewUrl;if(ocrPreviewUrl){const url=ocrPreviewUrl;img.src=url;img.onerror=()=>{if(url!==ocrPreviewUrl)return;cancelOCR();ocrSelectedFile=null;img.hidden=true;if(run)run.disabled=true;const st=$('#ocr-status');if(st)st.textContent='這張相片讀不到。請改用 JPG／PNG，或直接貼文字。';};}if(name)name.textContent=importDraft.fileName?(importDraft.source==='camera'?'已拍攝：':'已選擇：')+importDraft.fileName:'未選擇圖片';if(run)run.disabled=!ocrSelectedFile||ocrBusy;}
