function updateViewport(){if(!document.body.classList.contains('quiz-active'))return;const vv=window.visualViewport,scaled=vv&&vv.scale>1.15;document.body.classList.toggle('zoomed-view',!!scaled);const height=vv?vv.height:innerHeight,top=vv?vv.offsetTop:0;document.documentElement.style.setProperty('--visible-height',height+'px');document.documentElement.style.setProperty('--visible-top',top+'px');const header=$('.header').getBoundingClientRect().height,issue=$('#save-issue')?.getBoundingClientRect().height||0;document.documentElement.style.setProperty('--quiz-header',header+issue+'px');document.body.classList.toggle('compact-quiz',height<550);document.body.classList.toggle('very-short-quiz',height<380);}

