/* WordQuest V13. Offline assets are separate from learning records.
   No remote image hotlinks. No persistence for guests. No provider secrets in this file. */
const MEDIA_DB=WQ_TEST_MODE?'wordquest-v29-test-media':'wordquest-media-v13';
const SHELL_CACHE='wordquest-v13-shell-793d608874a7';
let mediaPromise=null,mediaOwner='',mediaEpoch=0,mediaBusy=false,mediaAbort=null,mediaReady=false,mediaError='',mediaMessage='',mediaSelectedRange='';
let mediaCache=new Map(),mediaUrls=new Map(),mediaAudio=null,mediaAudioUrl='',mediaPreviewAudio=null,decodeContext=null,swState='未準備',shellReady=false;
const MAX_PACK=40*1024*1024,MAX_IMAGE=2*1024*1024,MAX_AUDIO=5*1024*1024;
const canonicalText=s=>String(s??'').normalize('NFC').trim().replace(/\s+/g,' ');
const own=()=>isLoggedIn()?accountId():'guest';
const imageKey=w=>'image:'+w.id+':'+canonicalText(w.en);
const audioKey=text=>'audio:en-GB:'+canonicalText(text);
const noteKey=w=>'note:'+w.id+':'+canonicalText(w.en);
const recordId=(owner,key)=>JSON.stringify([owner,key]);
function sourceURL(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:'';}catch(_){return '';}}
function plainText(html){return String(html||'').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim().slice(0,800);}
function metadataText(s,max=400){return String(s||'').replace(/[\u0000-\u001f]/g,' ').slice(0,max);}
function openMediaDb(){if(mediaPromise)return mediaPromise;mediaPromise=new Promise((resolve,reject)=>{
 if(!window.indexedDB){reject(Error('這個瀏覽器未能使用教材儲存。'));return;}
 const r=indexedDB.open(MEDIA_DB,1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('assets')){const s=d.createObjectStore('assets',{keyPath:'id'});s.createIndex('owner','owner',{unique:false});}};
 r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();mediaPromise=null;};resolve(r.result);};r.onerror=()=>{mediaPromise=null;reject(r.error||Error('未能開啟教材儲存。'));};r.onblocked=()=>{mediaError='請關閉同網站的其他分頁，再重試。';refreshMediaNotice();};
 });return mediaPromise;}
async function readMediaOwner(owner){const d=await openMediaDb();return new Promise((resolve,reject)=>{const tx=d.transaction('assets','readonly'),r=tx.objectStore('assets').index('owner').getAll(owner);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function revokeMediaUrls(){for(const url of mediaUrls.values())URL.revokeObjectURL(url);mediaUrls.clear();}
function cancelMediaJob(){mediaEpoch++;mediaBusy=false;mediaAbort?.abort();mediaAbort=null;}
async function syncMediaOwner(force=false){const owner=own();if(owner===mediaOwner&&mediaReady&&(!force||owner==='guest'))return;if(owner!==mediaOwner){mediaMessage='';mediaSelectedRange='';}cancelMediaJob();const epoch=mediaEpoch;stopMediaPlayback();revokeMediaUrls();mediaCache.clear();mediaReady=false;mediaError='';mediaOwner=owner;
 if(owner==='guest'){mediaReady=true;refreshMediaNotice();return;}
 try{const rows=await readMediaOwner(owner);if(epoch!==mediaEpoch||owner!==own())return;for(const row of rows){if(row.owner!==owner||typeof row.key!=='string')continue;if(row.kind==='note'||row.blob instanceof Blob)mediaCache.set(row.key,row);}mediaReady=true;}
 catch(e){if(epoch!==mediaEpoch)return;mediaError='教材暫時未能儲存。請保留備份，檢查瀏覽器儲存設定。';mediaReady=true;}
 refreshMediaNotice();if(lastRoute==='offline')renderOfflineContents();hydratePictures();renderAudioState();}
async function storeMedia(rows,expectedOwner=own()){if(!v24RequireParent(true))throw Error('家長授權失效或目前唯讀');const intent=v23Owner();
 if(expectedOwner!==own()||expectedOwner!==mediaOwner)throw Error('帳戶已切換，已取消儲存。');
 const clean=rows.map(r=>({...r,id:recordId(expectedOwner,r.key),owner:expectedOwner,updatedAt:new Date().toISOString()}));
 if(expectedOwner!=='guest'){const d=await openMediaDb();if(expectedOwner!==own())throw Error('帳戶已切換。');await new Promise((resolve,reject)=>{if(intent!==v23Owner()||!v24RequireParent(true))throw Error('授權已失效');const tx=d.transaction('assets','readwrite');for(const r of clean)tx.objectStore('assets').put(r);tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||Error('教材寫入失敗。'));tx.onerror=()=>{};});}
 if(expectedOwner!==own())return;for(const r of clean){const old=mediaUrls.get(r.key);if(old)URL.revokeObjectURL(old);mediaUrls.delete(r.key);mediaCache.set(r.key,r);}mediaError='';}
async function removeMedia(key,owner=own()){if(!v24RequireParent(true))throw Error('家長授權失效或目前唯讀');const intent=v23Owner();if(owner!==own())throw Error('帳戶已切換。');if(owner!=='guest'){const d=await openMediaDb();await new Promise((resolve,reject)=>{if(owner!==own()||intent!==v23Owner()||!v24RequireParent(true))throw Error('身份或授權已改變');const tx=d.transaction('assets','readwrite');tx.objectStore('assets').delete(recordId(owner,key));tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);});}if(owner!==own())return;const url=mediaUrls.get(key);if(url)URL.revokeObjectURL(url);mediaUrls.delete(key);mediaCache.delete(key);}
async function clearAccountMedia(owner){cancelMediaJob();try{const rows=owner==='guest'?[]:await readMediaOwner(owner);if(owner!=='guest'){const d=await openMediaDb();await new Promise((resolve,reject)=>{const tx=d.transaction('assets','readwrite');for(const r of rows)tx.objectStore('assets').delete(r.id);tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);});}if(owner===own()){stopMediaPlayback();revokeMediaUrls();mediaCache.clear();mediaMessage='這個帳戶的離線素材已清除。';refreshMediaNotice();}}catch(e){if(owner===own())toast('學習資料已重設，但離線素材未能清除。請檢查瀏覽器儲存設定。','bad');}}
function mediaEntry(key){return mediaOwner===own()?mediaCache.get(key):null;}
function mediaURL(entry){if(!entry?.blob)return '';if(!mediaUrls.has(entry.key))mediaUrls.set(entry.key,URL.createObjectURL(entry.blob));return mediaUrls.get(entry.key);}
function imageFor(w){const custom=mediaEntry(imageKey(w));if(custom?.blob)return {src:mediaURL(custom),custom:true,meta:custom};const note=mediaEntry(noteKey(w));if(note?.textOnly)return null;const m=MEDIA_CATALOG[norm(w.en)];if(m)return {src:BUILTIN_IMAGES[m.image],custom:false,meta:m};return null;}
function picture(w,small=false){if(!w)return '';const entry=imageFor(w);return entry?`<div class="picture asset-picture" data-picture-word="${esc(w.id)}" aria-hidden="true"><img src="${esc(entry.src)}" alt="" draggable="false" data-media-word="${esc(w.id)}"></div>`:`<div class="picture fallback media-no-picture" data-picture-word="${esc(w.id)}" aria-hidden="true"><span>看文字</span></div>`;}
function hydratePictures(){document.querySelectorAll('[data-picture-word]').forEach(box=>{const w=db.words.find(w=>w.id===box.dataset.pictureWord);if(w)box.outerHTML=picture(w);});}
function expectedAudio(w){const out=[w.en];if(w.kind!=='sentence'&&w.example&&canonicalText(w.example)!==canonicalText(w.en))out.push(w.example);return [...new Set(out.map(canonicalText))];}
function usableAudio(text){const r=mediaEntry(audioKey(text));return r?.blob instanceof Blob&&r.blob.size>44&&r.locale==='en-GB'&&r.verified===true?r:null;}
function wordMediaStatus(w){const image=imageFor(w),note=mediaEntry(noteKey(w));const texts=expectedAudio(w);return {image:!!image,textOnly:!!note?.textOnly,checked:note?.imageChecked===true,wordAudio:!!usableAudio(w.en),texts,missing:texts.filter(t=>!usableAudio(t))};}
function mediaRange(){return childRanges().find(r=>r.id===mediaSelectedRange)||latestRange();}
function rangeMediaStatus(r=mediaRange()){const ws=r?rangeWords(r.id):[],states=ws.map(w=>wordMediaStatus(w));return {total:ws.length,images:states.filter(s=>s.image).length,missingImages:states.filter(s=>!s.image&&!s.textOnly).length,unchecked:states.filter(s=>s.image&&!s.checked).length,audioTotal:states.reduce((n,s)=>n+s.texts.length,0),missingAudio:states.reduce((n,s)=>n+s.missing.length,0),ready:ws.length>0&&mediaReady&&!mediaError&&states.every(s=>(s.image&&s.checked||s.textOnly)&&s.missing.length===0)};}
function offlineView(){return `${navTabs('offline')}<div class="row between"><div><div class="eyebrow">家長 · 圖片與讀音</div><h1>離線教材</h1></div>${link('返回孩子頁','kid','soft')}</div><p class="muted">先準備，出街沒有網絡也可以練習。</p><div id="offline-content"></div>`;}
function summaryCard(){const r=mediaRange(),s=rangeMediaStatus(r);return `<div class="offline-summary card pad"><div class="row between"><h2>${s.ready?'教材已齊備':'還有內容要準備'}</h2><span class="chip">${navigator.onLine?'目前有網絡':'目前沒有網絡'}</span></div><div class="offline-counts"><div><strong>${s.total-s.missingImages}/${s.total}</strong><span>配圖或文字教學</span></div><div><strong>${s.audioTotal-s.missingAudio}/${s.audioTotal}</strong><span>已存英式音檔</span></div><div><strong>${shellReady?'已準備':'待檢查'}</strong><span>離線開啟網頁</span></div></div><p class="small muted">${s.ready?'這份教材的圖片已核對、音檔已儲存。':'未有音檔的聽力題可先跳過，不會計錯。'}${s.unchecked?' 還有 '+s.unchecked+' 張配圖要核對。':''}</p><p class="small muted">${location.protocol==='file:'?'你正使用已下載的 HTML；請保留這個檔案。額外素材只存於目前瀏覽器，換裝置前請匯出教材包。':shellReady?'網頁已可離線重開；出門前仍建議開飛行模式測一次。':'先按「準備網頁」，才可在斷網後重新開啟。'}</p>${!isLoggedIn()?`<div class="notice">訪客可試用，但新增教材、圖片及音檔不會永久保存。${link('登入儲存','login','soft')}</div>`:''}${mediaError?`<div class="dangerbox">${esc(mediaError)}</div>`:''}<div class="row media-actions"><button class="btn primary" data-act="prepare-media" ${mediaBusy||!r?'disabled':''}>${mediaBusy?'正在準備…':'準備離線教材'}</button><button class="btn secondary" data-act="check-media" ${mediaBusy?'disabled':''}>重新檢查</button>${mediaBusy?btn('停止下載','cancel-media','secondary'):''}</div><p id="media-job-status" role="status" class="small muted">${esc(mediaMessage)}</p><details class="offline-extra"><summary>下載來源及其他工具</summary><p class="small muted">下載只傳送核對後的英文內容，不附上帳戶中的孩子姓名、答題紀錄或原相片。英文內容本身若有姓名等個人資料，請先刪去或改用自行補音檔。公共英式錄音來自 Wikimedia Commons；如網站管理員已接好 Microsoft 英式語音，亦可生成固定音檔。並非每個字都有公共錄音；read、lead 等多讀音字仍要按詞義核對。</p><label class="media-consent"><input id="media-network-consent" type="checkbox">同意這次連線取得英文錄音</label><div class="row">${btn('準備網頁','prepare-shell','secondary')}${btn('要求保留儲存空間','persist-storage','secondary')}${btn('檢查儲存空間','storage-status','secondary')}</div><p id="storage-status" class="small muted"></p><div class="row">${btn('匯出這份教材包','export-media','secondary')}${btn('匯入教材包','import-media','secondary')}</div><p class="small muted">教材包含生字、圖片及音檔，不包含孩子姓名、金幣或答題紀錄。學習紀錄請另到「設定／備份」匯出。</p>${link('素材來源','credits','quiet')}<p class="small muted">${esc(swState)}。${isLoggedIn()?'額外素材以這個本機帳戶分開儲存。':'訪客素材只保留到離開或重新載入。'}</p></details></div>`;}
function renderOfflineContents(){const box=$('#offline-content');if(!box)return;const r=mediaRange(),ws=r?rangeWords(r.id):[];
 box.innerHTML=`<div class="field" style="margin:18px 0"><label for="media-range">默書範圍</label><select id="media-range">${childRanges().map(x=>`<option value="${esc(x.id)}" ${x.id===r?.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>${summaryCard()}${ws.length?`<div class="row between" style="margin:22px 0 10px"><h2>逐項核對</h2>${btn('確認現有配圖合適','confirm-pictures','secondary',mediaBusy?'disabled':'')}</div><p class="small muted">同一個字可能有不同意思。請按今次默書的意思核對配圖；「because」等抽象字可選文字教學。</p>`:'<p class="notice">請先加入默書範圍。</p>'}<div class="media-list">${ws.map(w=>mediaWordCard(w)).join('')}</div>`;}
function mediaWordCard(w){const s=wordMediaStatus(w);return `<article class="card media-word" data-media-row="${esc(w.id)}"><div class="media-art">${picture(w,true)}</div><div class="media-word-body"><h3 lang="en">${esc(w.en)}</h3><p>${esc(w.zh||'未填中文意思')}</p><div class="media-tags"><span>${s.image?s.checked?'配圖已核對':'配圖待核對':s.textOnly?'改用文字教學':'待補圖片'}</span><span>${s.wordAudio?'生字音檔已存':'待補生字讀音'}</span>${s.texts.length>1?`<span>${s.missing.includes(w.example)?'例句音檔未存':'例句音檔已存'}</span>`:''}</div><div class="row"><button class="btn soft" data-act="preview-media" data-wid="${esc(w.id)}" ${s.wordAudio?'':'disabled'}>聽讀音</button><button class="btn secondary" data-act="edit-media" data-wid="${esc(w.id)}">補圖／讀音</button></div></div></article>`;}
function refreshMediaNotice(){const s=rangeMediaStatus(latestRange()),el=$('#parent-media-summary');if(el)el.textContent=mediaError?'教材儲存需要處理':s.ready?'圖片及讀音已準備好':'圖片／讀音仍有待準備';}
function mediaDialog(w){stopMediaPlayback();const existing=$('#media-editor');existing?.remove();const d=document.createElement('dialog');d.id='media-editor';d.className='media-dialog';d.innerHTML=`<div class="pad"><div class="row between"><h2>${esc(w.en)}</h2><button class="btn quiet" data-act="close-media-editor">關閉</button></div><p>${esc(w.zh||'請按今次默書意思核對。')}</p><div class="media-dialog-art">${picture(w)}</div><label class="field">更換圖片（JPG／PNG／WebP）<input id="media-image-file" type="file" accept="image/jpeg,image/png,image/webp" data-wid="${esc(w.id)}"></label><p class="small muted">相片只在這個裝置處理，會縮圖並移除檔案的原始中繼資料。</p><div class="row"><button class="btn secondary" data-act="text-only" data-wid="${esc(w.id)}">這個字用文字教學</button><button class="btn secondary" data-act="reset-word-image" data-wid="${esc(w.id)}">恢復預設配圖</button></div><hr><h3>補上英式音檔</h3><label class="field">音檔對應內容<select id="media-audio-target">${expectedAudio(w).map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label><input id="media-audio-file" type="file" accept="audio/mpeg,audio/wav,audio/x-wav,audio/mp4,audio/ogg,audio/webm" data-wid="${esc(w.id)}"><p class="small muted">請使用有權使用的英式錄音。系統會檢查檔案可否播放，但不會自動證明口音或內容正確。</p><label class="media-consent"><input id="confirm-audio-uk" type="checkbox">我已聽過，確認是上方內容的英式讀音，並有權使用</label><button class="btn primary" data-act="save-uploaded-audio" data-wid="${esc(w.id)}">儲存這個音檔</button><p id="media-editor-status" role="status" class="small"></p></div>`;document.body.appendChild(d);d.addEventListener('close',()=>{stopPreviewAudio();d.remove();});d.showModal();}
async function validatedImage(blob){if(blob.size>MAX_IMAGE*5||!/^image\/(png|jpeg|webp)$/.test(blob.type))throw Error('請用 10 MB 以內的 JPG、PNG 或 WebP。');const url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await Promise.race([img.decode(),new Promise((_,r)=>setTimeout(()=>r(Error('圖片讀取逾時。')),8000))]);if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>40000000)throw Error('圖片太大或無法讀取。');const ratio=Math.min(1,640/img.naturalWidth,640/img.naturalHeight);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*ratio));c.height=Math.max(1,Math.round(img.naturalHeight*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);const out=await new Promise(r=>c.toBlob(r,'image/png'));if(!out||out.size>MAX_IMAGE)throw Error('圖片未能縮小。');return out;}finally{URL.revokeObjectURL(url);}}
async function decodeClip(blob){if(!(blob instanceof Blob)||blob.size<44||blob.size>MAX_AUDIO)throw Error('請使用 5 MB 以內的有效音檔。');const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error('這個瀏覽器未能處理音檔。');decodeContext=decodeContext||new A();const audio=await Promise.race([decodeContext.decodeAudioData(await blob.arrayBuffer()),new Promise((_,r)=>setTimeout(()=>r(Error('音檔讀取逾時。')),10000))]);if(!Number.isFinite(audio.duration)||audio.duration<.08||audio.duration>60)throw Error('音檔須介乎 0.08 至 60 秒。');return audio;}
function wavFromBuffer(b){const rate=24000,n=Math.floor(b.duration*rate),out=new ArrayBuffer(44+n*2),v=new DataView(out),str=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};str(0,'RIFF');v.setUint32(4,36+n*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*2,true);const channels=Array.from({length:b.numberOfChannels},(_,i)=>b.getChannelData(i));for(let i=0;i<n;i++){const p=i*b.sampleRate/rate,j=Math.floor(p),f=p-j;let x=0;for(const c of channels)x+=(c[Math.min(j,c.length-1)]*(1-f)+c[Math.min(j+1,c.length-1)]*f)/channels.length;v.setInt16(44+i*2,Math.round(Math.max(-1,Math.min(1,x))*32767),true);}return new Blob([out],{type:'audio/wav'});}
async function handleImageUpload(wid,file){const owner=own(),w=childWords().find(w=>w.id===wid);if(!w||!file)return;try{const blob=await validatedImage(file);if(owner!==own()||!childWords().some(x=>x.id===wid))throw Error('孩子或帳戶已切換。');await storeMedia([{kind:'image',key:imageKey(w),blob,source:'家長上傳',license:'使用者提供',verified:true},{kind:'note',key:noteKey(w),imageChecked:true,textOnly:false}],owner);$('#media-editor')?.close();renderOfflineContents();toast(owner==='guest'?'已加入試玩圖片；離開後不會保存。':'圖片已儲存。');}catch(e){editorMessage(e.message);}}
function editorMessage(t){const el=$('#media-editor-status');if(el)el.textContent=t;else{mediaError=t;renderOfflineContents();}}
async function saveUploadedAudio(wid){const owner=own(),w=childWords().find(w=>w.id===wid),f=$('#media-audio-file')?.files[0],target=$('#media-audio-target')?.value;if(!w||!expectedAudio(w).includes(target))return;if(!f||!$('#confirm-audio-uk')?.checked){editorMessage('請先選音檔，並核對內容及英式發音。');return;}const button=$('[data-act="save-uploaded-audio"]');button.disabled=true;try{const b=await decodeClip(f);if(owner!==own()||!childWords().some(x=>x.id===wid))throw Error('孩子或帳戶已切換。');await storeMedia([{kind:'audio',key:audioKey(target),text:target,blob:wavFromBuffer(b),duration:b.duration,locale:'en-GB',verified:true,source:'家長核對的英式錄音',credit:'使用者提供',license:'使用者提供'}],owner);$('#media-editor')?.close();renderOfflineContents();toast('音檔已儲存，可離線播放。');}catch(e){editorMessage(e.message);}finally{if(button.isConnected)button.disabled=false;}}
async function getLimited(url,max,options={}){const r=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',...options});if(!r.ok)throw Error('下載失敗（'+r.status+'）。');if(Number(r.headers.get('content-length'))>max)throw Error('檔案過大。');if(!r.body)return new Blob([await r.arrayBuffer()],{type:r.headers.get('content-type')||''});const reader=r.body.getReader(),parts=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>max){await reader.cancel();throw Error('檔案過大。');}parts.push(value);}return new Blob(parts,{type:(r.headers.get('content-type')||'').split(';')[0]});}
function wikiName(text){return canonicalText(text).toLowerCase().replace(/ /g,'_');}
function validWikiMeta(page,text){const info=page?.imageinfo?.[0],m=info?.extmetadata||{},lic=plainText(m.LicenseShortName?.value),url=sourceURL(info?.url),author=plainText(m.Artist?.value),description=plainText(m.ImageDescription?.value),title=(page?.title||'').replace(/_/g,' ');const exact=title.toLowerCase()==='file:en-uk-'+canonicalText(text).toLowerCase()+'.ogg';const allowed=/^(CC BY(?:-SA)? (?:2\.0|2\.5|3\.0|4\.0)(?: US)?|CC0(?: 1\.0)?|Public domain)$/i.test(lic);if(!exact||!allowed||!author||!url||new URL(url).hostname!=='upload.wikimedia.org'||(info.size&&info.size>MAX_AUDIO))return null;return {url,locale:'en-GB',source:sourceURL(info.descriptionurl)||'https://commons.wikimedia.org/wiki/'+encodeURIComponent(page.title),credit:author,license:lic,licenseUrl:sourceURL(m.LicenseUrl?.value),description,verified:true};}
async function fetchUKRecording(text,signal){if(!/^[A-Za-z][A-Za-z '’-]{0,79}$/.test(text))throw Error('這個詞組或句子需要補上音檔。');const name='File:En-uk-'+wikiName(text)+'.ogg';const params=new URLSearchParams({action:'query',format:'json',origin:'*',prop:'imageinfo',iiprop:'url|extmetadata|mime|size',iiextmetadatalanguage:'en',titles:name});const metaBlob=await getLimited('https://commons.wikimedia.org/w/api.php?'+params,300000,{signal});const data=JSON.parse(await metaBlob.text()),pages=Object.values(data?.query?.pages||{});const source=pages.map(p=>validWikiMeta(p,text)).find(Boolean);if(!source)throw Error('未找到已標示英式、可使用的錄音。');const blob=await getLimited(source.url,MAX_AUDIO,{signal}),buffer=await decodeClip(blob);return {kind:'audio',key:audioKey(text),text:canonicalText(text),blob:wavFromBuffer(buffer),duration:buffer.duration,...source,transform:'converted to 24 kHz mono PCM WAV for offline playback'};}
async function neuralAvailable(signal){if(location.protocol==='file:')return false;try{const r=await fetch('./api/tts/status',{signal,cache:'no-store',credentials:'same-origin'});if(!r.ok||!(r.headers.get('content-type')||'').includes('json'))return false;return (await r.json()).enabled===true;}catch(_){return false;}}
async function fetchNeural(text,signal){const b=await getLimited('./api/tts',MAX_AUDIO,{method:'POST',headers:{'Content-Type':'application/json','X-WordQuest-Request':'v13'},credentials:'same-origin',body:JSON.stringify({text,locale:'en-GB'}),signal});const decoded=await decodeClip(b);return {kind:'audio',key:audioKey(text),text,blob:wavFromBuffer(decoded),duration:decoded.duration,locale:'en-GB',verified:true,source:'Microsoft Azure Speech · en-GB-SoniaNeural',credit:'網站管理員配置的 Microsoft Speech 服務',license:'服務輸出；請依服務條款使用',transform:'converted to 24 kHz mono PCM WAV'};}
async function prepareMedia(){if(mediaBusy)return;await syncMediaOwner();const r=mediaRange();if(!r)return;const consent=$('#media-network-consent')?.checked;if(!consent){const details=$('.offline-extra');if(details)details.open=true;$('#media-network-consent')?.focus();mediaMessage='先勾選下載同意，才會傳送英文項目取得錄音。';const m=$('#media-job-status');if(m)m.textContent=mediaMessage;return;}if(!navigator.onLine){mediaMessage='目前沒有網絡。已存素材仍可用；新音檔可稍後再準備。';renderOfflineContents();return;}
 const owner=own(),rid=r.id,cid=activeChild()?.id,ws=rangeWords(rid).map(w=>({...w})),todo=[...new Set(ws.flatMap(expectedAudio))].filter(t=>!usableAudio(t));cancelMediaJob();const epoch=mediaEpoch;mediaBusy=true;mediaAbort=new AbortController();const controller=mediaAbort,signal=controller.signal;const valid=()=>epoch===mediaEpoch&&owner===own()&&cid===activeChild()?.id&&childRanges().some(x=>x.id===rid);let ok=0,failed=[];
 mediaMessage='正在準備網頁及檢查英式音源…';renderOfflineContents();if(location.protocol!=='file:'&&'serviceWorker' in navigator&&isSecureContext){await prepareShell();if(!valid())return;}else await checkShell();const neural=await neuralAvailable(signal);if(!valid())return;
 for(let i=0;i<todo.length;i++){if(!valid())break;const text=todo[i];mediaMessage=`準備 ${i+1}/${todo.length}：${text}`;const el=$('#media-job-status');if(el)el.textContent=mediaMessage;
 const timer=setTimeout(()=>controller.abort(),20000);
 try{const row=neural?await fetchNeural(text,signal):await fetchUKRecording(text,signal);if(!valid())break;await storeMedia([row],owner);ok++;}
 catch(e){if(!valid())break;failed.push(text);if(signal.aborted){mediaMessage='下載逾時，已保留成功項目。可再次準備剩下的音檔。';break;}}
 finally{clearTimeout(timer);}
 }
 if(valid()){mediaBusy=false;mediaAbort=null;mediaMessage=`已新增 ${ok} 段英式錄音。${failed.length?' '+failed.length+' 項未取得，可重試或自行補音檔。':' 已有音檔不會重複下載。'}`;renderOfflineContents();refreshMediaNotice();}
}
