let v20=v20Fresh(),v20Photo=null,v20PhotoEpoch=0,v20FileLoading=false,v20Origin=null;
function v20Owner(){return (accountId()||'guest')+'|'+(activeChild()?.id||'');}
function v20History(){v20.history.push({items:V20.clone(v20.items),documents:v20.documents.slice(),raw:importDraft.raw,parsedRaw:v20.parsedRaw,rawDirty:v20.rawDirty,mode:v20.mode,common:[...v20.common]});if(v20.history.length>20)v20.history.shift();}
function v20Touch(){v20.revision++;v20.editing=true;importDraft.confirmed=false;if(ocrBusy){cancelOCR();v20.message='你已修改選詞，這次辨認已停止；原有更正會保留。';updateImportPhoto();}const cb=$('#confirm-import');if(cb)cb.checked=false;}
function v20Kind(c){return c.kind==='sentence'?'整句':c.kind==='phrase'?'詞組':'生字';}
function v20Recheck(c){const g=V20.gloss(c.en,v20Dictionary);c.known=g.known;c.choices=g.choices;c.example=g.example;c.common=v20.common.has(V20.fold(c.en))&&!/\s/.test(c.en)&&c.kind!=='sentence';return c;}
function v20KnownWords(){const map=new Map();if(!isLoggedIn())return map;const words=new Map(childWords().map(w=>[w.id,w]));for(const a of db.attempts){if(!words.has(a.wordId)||!['spell','listenSpell','cloze'].includes(a.type)||a.assisted||a.technical)continue;const w=words.get(a.wordId),k=w.en+'|'+(w.zh||''),old=map.get(k);if(!old||a.time>old.time)map.set(k,a);}return map;}
function v20Info(c){if(V20.pending(c))return '請核對';if(c.reviewed)return '已核對';if(c.excludedReason)return '未加入';return c.kind==='phrase'?'整個詞組':c.common?'常用字':'按一下取消';}
function v20Selected(){return V20.selected(v20.items);}
function v20Pending(){return v20.items.filter(V20.pending);}
function v20SyncDraft(){draftWords=v20Selected().map(c=>({en:c.en,zh:c.zh,kind:c.kind}));}
function v20Card(c,known){const isKnown=known.get(c.en+'|'+c.zh)?.correct===true;return `<article class="v20-candidate ${c.selected?'is-selected':''} ${V20.pending(c)?'is-review':''} ${v20.mergeStart===c.id?'merge-start':''}" data-candidate-id="${esc(c.id)}"><button class="v20-token" type="button" data-imp="toggle" data-id="${esc(c.id)}" aria-pressed="${c.selected}" aria-label="${c.selected?'取消':'加入'} ${esc(c.en)}"><span class="tick" aria-hidden="true">${c.selected?'✓':''}</span><span class="txt"><strong lang="en-GB">${esc(c.en)}</strong><small>${esc(c.zh||'中文可稍後補上')}</small>${isKnown?'<small>曾經自己串對</small>':''}</span></button><div class="v20-candidate-foot"><span>${v20Info(c)}${c.occurrences>1?' · '+c.occurrences+' 處':''}</span><button type="button" data-imp="edit" data-id="${esc(c.id)}" aria-label="核對或修改 ${esc(c.en)}">${V20.pending(c)?'核對':'修改'}</button></div></article>`;}
rangeNewView=function(){return `${navTabs('ranges')}<section class="import-v20" id="import-v20"><div class="row between"><div><div class="eyebrow">家長 · 默書範圍</div><h1>拍好，選字，就能練。</h1><p class="small muted">先整理，再由你選今次要默的內容。</p></div>${link('返回','ranges','quiet')}</div><div class="v20-stepper" aria-label="匯入步驟"><span>1 加入相片／文字</span><span>2 點選字詞</span><span>3 核對及加入</span></div><div class="v20-layout"><section class="card v20-source"><h2>1. 加入範圍</h2><div class="form-grid"><div class="v20-field"><label for="range-title">名稱</label><input id="range-title" maxlength="120" placeholder="例如 Unit 4" value="${esc(importDraft.title)}"></div><div class="v20-field"><label for="range-date">默書日期（可不填）</label><input id="range-date" type="date" value="${esc(importDraft.date)}"></div></div><div class="v20-choices"><button class="btn secondary" data-act="open-camera"><span class="ico" aria-hidden="true">📷</span>拍照</button><button class="btn secondary" data-act="open-upload"><span class="ico" aria-hidden="true">🖼️</span>上傳圖片</button></div><input id="ocr-camera" type="file" accept="image/*" capture="environment" hidden><input id="ocr-upload" type="file" accept="image/*" hidden><div id="ocr-file-name" class="v20-file-name">未選擇圖片</div><div class="v20-photo"><img id="ocr-preview" alt="所選默書相片" hidden></div><div class="v20-toolbar" id="v20-photo-tools" ${v20Photo?'':'hidden'}><button class="btn secondary" data-imp="crop">框選／拉直</button><button class="btn quiet" data-imp="full-photo">看原相</button></div><div class="row"><button class="btn primary" data-act="run-ocr" id="run-ocr" disabled>辨認所選範圍</button><button class="btn quiet" data-imp="cancel-ocr" id="v20-cancel-ocr" hidden>停止</button></div><div id="ocr-progress" class="v20-progress" hidden><span></span></div><div id="ocr-status" class="v20-inline-status" role="status"></div><details id="v20-text-details" ${importDraft.raw||!v20Photo?'open':''}><summary>或直接貼上文字</summary><div class="v20-field"><label for="raw-words">原文（保留作對照）</label><textarea id="raw-words" maxlength="30000" spellcheck="false" placeholder="apple banana orange&#10;ice cream&#10;school bag&#10;&#10;也可每行輸入：英文 | 中文">${esc(importDraft.raw)}</textarea></div><button class="btn secondary full" data-imp="parse">整理成可選字詞</button></details><details><summary>相片辨認及私隱</summary><p class="small muted">先裁走姓名、校名等個人資料。只辨認打印英文；首次載入辨認引擎及英文資料需要網絡。相片在瀏覽器處理，不傳到辨認伺服器。辨認結果仍要對照原稿。</p><p class="small muted">原相及未儲存的草稿只保留在目前分頁；重新載入或關閉後會失去。加入教材只保存已選字詞和對應文字片段，不保存整張原相。</p><div class="v20-field"><label for="v20-psm">版面處理</label><select id="v20-psm"><option value="3">自動分欄</option><option value="6">已框選的一欄文字</option><option value="11">分散的生字表</option></select></div><label class="v20-check"><input type="checkbox" id="v20-enhance">稍為加強文字對比</label></details></section><section class="card v20-selection"><div class="row between"><h2>2. 點選字詞</h2><button class="btn quiet" data-imp="add" style="font-size:14px">＋ 自己加入</button></div><div class="v20-modes" role="group" aria-label="選取方式">${[['list','生字清單','整行多字會拆開'],['passage','文章挑字','常用字可略過'],['sentences','整句默書','保留字詞及標點']].map(([k,t,s])=>`<button class="v20-mode" data-imp="mode" data-value="${k}" aria-pressed="${v20.mode===k}"><strong>${t}</strong><small>${s}</small></button>`).join('')}</div><p class="v20-mode-note" id="v20-mode-note"></p><div id="v20-message" class="v20-inline-status" role="status"></div><div id="word-editor"></div></section></div><div class="v20-selected-footer" id="v20-import-dock"><div class="inner"><div><strong id="v20-selected-count">已選 0 項</strong><small id="v20-pending-count">最多 120 項</small></div><button class="btn primary" data-imp="summary" id="v20-confirm-next" disabled>核對及加入 →</button></div></div></section>`;};
renderWordEditor=function(){v20RenderWords();};
syncDraftInputs=function(){v20SyncDraft();};
captureImportDraft=function(){if(skipImportCapture){skipImportCapture=false;return;}if(!$('#range-title'))return;importDraft.title=$('#range-title').value;importDraft.date=$('#range-date').value;if($('#raw-words'))importDraft.raw=$('#raw-words').value;if($('#confirm-import'))importDraft.confirmed=$('#confirm-import').checked;v20SyncDraft();};
restoreImportDraft=function(){if(!$('#range-title'))return;$('#range-title').value=importDraft.title;$('#range-date').value=importDraft.date;$('#raw-words').value=importDraft.raw;v20RenderWords();updateImportPhoto();};
const v20PreviousClear=clearImportDraft;
clearImportDraft=function(){v20PhotoEpoch++;v20CloseAll();for(const d of v20.documents||[])if(d.previewURL)URL.revokeObjectURL(d.previewURL);if(v20Photo?.originalURL)URL.revokeObjectURL(v20Photo.originalURL);v20Photo=null;v20FileLoading=false;v20=v20Fresh();v20Origin=null;v20PreviousClear();};
function v20RenderWords(){const box=$('#word-editor');if(!box)return;v20SyncDraft();const note=$('#v20-mode-note');if(note)note.textContent={list:'清單中的短字也會保留；相同拼法和詞組都由你核對。',passage:'先全選，按需要略過常用字。只改選取，不改原句。',sentences:'保留完整句子、大小寫及標點，不移除常用字。多欄請逐欄框選。'}[v20.mode];$$('[data-imp="mode"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===v20.mode));
 const msg=$('#v20-message');if(msg)msg.textContent=v20.rawDirty?'原文已修改，請按「整理成可選字詞」；原有選詞暫時保留。':v20.message;
 const selection=v20Selected(),pend=v20Pending();$('#v20-selected-count').textContent=`已選 ${selection.length} / 120 項`;$('#v20-pending-count').textContent=pend.length?`${pend.length} 項需核對 · 可修改或略過`:selection.length?'按一下字塊可取消':'先加入相片或文字';$('#v20-confirm-next').disabled=!selection.length||v20.rawDirty||v20FileLoading||ocrBusy;$('#v20-confirm-next').textContent=pend.length?`核對 ${pend.length} 項 →`:'核對及加入 →';
 if(!v20.items.length){box.innerHTML='<div class="v20-empty"><div class="empty-mark" aria-hidden="true">Aa ✓</div><p>拍照、上傳或貼上文字。<br>這裏會變成可點選的字詞。</p></div>';return;}
 const known=v20KnownWords(),excluded=v20.items.filter(c=>c.excludedReason&&!c.selected),all=v20.items.filter(c=>!c.excludedReason||c.selected),common=v20.mode==='passage'?all.filter(c=>c.common):[];
 const filter=items=>items.filter(c=>v20.filter==='review'?V20.pending(c):v20.filter==='unselected'?!c.selected:true);const normal=filter(v20.mode==='passage'?all.filter(c=>!c.common):all);const subset=normal.slice(0,v20.showLimit);
 const commonRows=filter(common);const duplicateCount=selection.length-new Set(selection.map(c=>c.en+'\u0000'+c.zh)).size;
 box.innerHTML=`<div class="v20-filter" role="group" aria-label="篩選字詞">${[['all','全部'],['review',`需核對 ${pend.length}`],['unselected','未選']].map(([k,t])=>`<button data-imp="filter" data-value="${k}" aria-pressed="${v20.filter===k}">${t}</button>`).join('')}</div><div class="v20-toolbar"><button class="btn quiet" data-imp="select-all">全選教材</button><button class="btn quiet" data-imp="select-none">取消全選</button><button class="btn quiet" data-imp="merge-mode" aria-pressed="${v20.mergeMode}">${v20.mergeMode?'取消合併':'合併字詞'}</button><button class="btn quiet" data-imp="undo" ${v20.history.length?'':'disabled'}>復原</button></div>${v20.mode==='passage'&&common.length?`<div class="v20-toolbar"><button class="btn secondary" data-imp="skip-common">略過常用字（${common.length}）</button><span class="small muted">原句及詞組不會改動</span></div>`:''}${v20.mergeMode?`<p class="v20-review-notice">${v20.mergeStart?'再按同一行的最後一個字。':'按同一行的第一個字，再按最後一個字。'}合併只調整選詞，不改原稿。</p>`:''}${duplicateCount?`<p class="v20-review-notice">有 ${duplicateCount} 個完全相同的已選項目。<button class="btn quiet" data-imp="dedupe">合併相同項目</button></p>`:''}<div class="v20-grid ${v20.mode==='sentences'?'sentences':''}">${subset.map(c=>v20Card(c,known)).join('')||'<p class="small muted">這組暫時沒有字詞。</p>'}</div>${normal.length>subset.length?`<button class="btn secondary full" data-imp="more">再顯示 ${Math.min(120,normal.length-subset.length)} 項（還有 ${normal.length-subset.length} 項）</button>`:''}${v20.mode==='passage'&&common.length?`<details class="v20-common" ${v20.filter==='review'?'open':''}><summary>常用字 ${common.length} 項 · 已選 ${common.filter(c=>c.selected).length} 項</summary><p class="small muted">這只是常用字分組，不代表孩子已會串。</p><div class="v20-toolbar"><button class="btn secondary" data-imp="skip-common">略過這組</button><button class="btn quiet" data-imp="select-common">全部加入</button><button class="btn quiet" data-imp="edit-common">更改分組</button></div><div class="v20-grid">${commonRows.slice(0,v20.showLimit).map(c=>v20Card(c,known)).join('')}</div></details>`:''}${excluded.length?`<details class="v20-excluded"><summary>未加入內容 ${excluded.length} 項</summary><p class="small muted">可能是頁首、姓名或日期。沒有刪走，需要時可恢復。</p>${excluded.map(c=>`<div class="v20-source-line"><div><p lang="en">${esc(c.en)}</p><small>${esc(c.excludedReason)}</small></div><button class="btn secondary" data-imp="restore" data-id="${esc(c.id)}">加入</button></div>`).join('')}</details>`:''}`;
}
function v20Parse(){captureImportDraft();const raw=importDraft.raw;if(!raw.trim()){toast('請先貼上英文，或用相片辨認。','bad');return;}if(raw.length>30000){toast('文字太長，請分開加入。','bad');return;}if(v20.items.length&&!confirm('按目前原文重新整理？目前點選及修改會重建，可以按「復原」返回。'))return;v20History();v20Touch();const doc=V20.fromText(raw,uid('text'));const items=V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common});if(items.length>1500){toast('內容太多，請分區或分段加入。','bad');return;}v20.documents=[doc];v20.items=items;v20.rawDirty=false;v20.parsedRaw=raw;v20.mergeMode=false;v20.filter='all';v20.showLimit=120;v20.message='已整理。按字塊選取；不確定的字可按「核對」。';v20RenderWords();$('#v20-mode-note')?.scrollIntoView({block:'start'});}
function v20ChangeMode(mode){if(!['list','passage','sentences'].includes(mode)||mode===v20.mode)return;if(v20.items.length&&!confirm('換選取方式會重新分詞及全選教材；你的原文仍然保留，可以按「復原」返回。'))return;const docs=v20.rawDirty?[V20.fromText(importDraft.raw,uid('text'))]:v20.documents;const items=docs.flatMap(d=>V20.candidates(d,{mode,dictionary:v20Dictionary,common:v20.common}));if(items.length>1500){toast('項目太多，請縮小範圍再整理。','bad');return;}v20History();v20Touch();v20.mode=mode;v20.documents=docs;v20.items=items;v20.filter='all';v20.rawDirty=false;v20.parsedRaw=importDraft.raw;v20.mergeMode=false;v20.message='已換選取方式。常用字不會自動取消。';v20RenderWords();}
function v20Undo(){const state=v20.history.pop();if(!state)return;v20Touch();Object.assign(v20,state);v20.common=new Set(state.common||V20.COMMON);importDraft.raw=state.raw;$('#raw-words').value=state.raw;v20.mergeMode=false;v20.message='已復原上一個操作。';v20RenderWords();}
function v20CloseAll(){for(const d of $$('.v20-dialog')){try{d.close();}catch(_){}d.remove();}}
function v20Dialog(title,body,foot='',id='v20-dialog'){const current=$('#'+id);current?.remove();const origin=document.activeElement;const d=document.createElement('dialog');d.id=id;d.className='v20-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<header class="v20-dialog-head"><h2>${esc(title)}</h2><button type="button" data-imp="close-dialog">關閉</button></header><div class="v20-dialog-body">${body}</div>${foot?`<footer class="v20-dialog-foot">${foot}</footer>`:''}`;document.body.append(d);d.addEventListener('close',()=>{d.remove();if(origin?.isConnected)origin.focus({preventScroll:true});});d.showModal();d.querySelector('button')?.focus({preventScroll:true});return d;}
function v20SourceBody(c){const d=v20.documents.find(d=>d.id===c.sourceRegionId),b=V20.union(c.sourceBoxes);return `<p class="v20-source-label">原來辨認到：<strong lang="en">${esc(c.originalText)}</strong></p>${d?.previewURL?`<img class="v20-crop-snippet" id="v20-snippet" alt="這個字在辨認相片中的位置"><details><summary>看整個辨認範圍</summary><div class="v20-full-source"><img src="${esc(d.previewURL)}" alt="這次辨認的相片範圍">${b?`<span class="v20-box" style="left:${100*b.x0/d.width}%;top:${100*b.y0/d.height}%;width:${100*(b.x1-b.x0)/d.width}%;height:${100*(b.y1-b.y0)/d.height}%"></span>`:''}</div></details>`:''}<details ${!d?.previewURL?'open':''}><summary>對照原文</summary><p class="v20-snippet" lang="en">${esc(c.sourceText)}</p></details>${c.confidenceRaw!==null?`<details><summary>辨認資訊</summary><p class="small muted">辨認引擎分數：${Math.round(c.confidenceRaw)}，只供排序核對，並不是正確率。即使沒有提示，也可能有認錯或漏字。</p></details>`:''}`;}
function v20FillSnippet(c){const region=v20.documents.find(d=>d.id===c.sourceRegionId),el=$('#v20-snippet');if(!el||!region?.previewURL)return;const b=V20.union(c.sourceBoxes);if(!b){el.src=region.previewURL;return;}const image=new Image();image.onload=()=>{if(!el.isConnected)return;const pad=Math.max(12,(b.y1-b.y0)*.8),x=Math.max(0,b.x0-pad),y=Math.max(0,b.y0-pad),w=Math.min(image.width-x,b.x1-b.x0+2*pad),h=Math.min(image.height-y,b.y1-b.y0+2*pad);if(w<=0||h<=0){el.src=region.previewURL;return;}const cv=document.createElement('canvas');cv.width=Math.min(1000,Math.max(250,w*2));cv.height=Math.max(35,Math.round(h*cv.width/w));cv.getContext('2d').drawImage(image,x,y,w,h,0,0,cv.width,cv.height);el.src=cv.toDataURL('image/png');};image.onerror=()=>{el.src=region.previewURL;};image.src=region.previewURL;}
function v20Edit(id){const c=v20.items.find(x=>x.id===id);if(!c)return;const sugg=V20.suggestions(c.en,v20Dictionary);const reasons=c.reviewReasons.length?`<p class="v20-review-notice">${esc(c.reviewReasons.join('；'))}。</p>`:'';const body=`${reasons}${v20SourceBody(c)}<div class="v20-field"><label for="v20-edit-en">今次要默的英文</label><input id="v20-edit-en" value="${esc(c.en)}" maxlength="240" autocomplete="off" autocapitalize="off" spellcheck="false"></div>${sugg.length?`<div class="v20-source-label">可能的拼法（不會自動更改）</div><div class="v20-suggest">${sugg.map(s=>`<button data-imp="suggest" data-value="${esc(s)}" lang="en">${esc(s)}</button>`).join('')}</div>`:''}<div class="v20-field"><label for="v20-edit-zh">今次的中文意思</label><input id="v20-edit-zh" maxlength="300" value="${esc(c.zh)}" placeholder="原稿未有中文，可以先留空"></div>${c.choices.length>1?`<div class="v20-suggest">${c.choices.map(s=>`<button data-imp="meaning" data-value="${esc(s)}">${esc(s)}</button>`).join('')}</div>`:''}<p class="small muted">保留原稿的單複數、時態及大小寫；詞庫未收錄的字也可以加入。</p><label class="v20-check"><input id="v20-item-checked" type="checkbox" ${c.reviewed?'checked':''}>我已核對這項英文及今次要教的意思</label><div id="v20-edit-error" role="alert"></div>`;
 const d=v20Dialog('核對字詞',body,`${/\s/.test(c.en)&&c.kind!=='sentence'?`<button class="btn secondary" data-imp="split" data-id="${esc(c.id)}">拆成單字</button>`:''}<button class="btn primary" data-imp="save-edit" data-id="${esc(c.id)}">保留修改</button>`,'v20-edit-dialog');v20FillSnippet(c);d.addEventListener('input',e=>{if(['v20-edit-en','v20-edit-zh'].includes(e.target.id))$('#v20-item-checked').checked=false;});}
function v20SaveEdit(id){const c=v20.items.find(x=>x.id===id);if(!c)return;const en=V20.exact($('#v20-edit-en').value),zh=$('#v20-edit-zh').value.trim(),checked=$('#v20-item-checked').checked;if(!validEnglish(en)||zh.length>300){$('#v20-edit-error').innerHTML='<p class="v20-error">請保留可用的英文、撇號或連字符；每項最多 240 字。</p>';return;}v20History();v20Touch();Object.assign(c,{en,zh,kind:c.kind==='sentence'?'sentence':kindOf(en),reviewed:checked,selected:true,edited:true});v20Recheck(c);if(!checked&&!c.reviewReasons.length)c.reviewReasons=['修改後請核對'];$('#v20-edit-dialog').close();v20.message=checked?'這項已核對。':'修改已保留，確認前請再核對。';v20RenderWords();if($('#v20-summary'))v20RenderSummary();}
function v20Add(){v20Dialog('自己加入字詞',`<div class="v20-field"><label for="v20-add-en">英文</label><input id="v20-add-en" maxlength="240" autocomplete="off" spellcheck="false"></div><div class="v20-field"><label for="v20-add-zh">中文意思（可不填）</label><input id="v20-add-zh" maxlength="300"></div><p class="small muted">原相漏了字，可以在這裏補回；也可以重新框選該部分。</p><p id="v20-add-error" role="alert"></p>`, '<button class="btn primary" data-imp="save-add">加入並選取</button>','v20-add-dialog');}
function v20SaveAdd(){const en=V20.exact($('#v20-add-en').value),zh=$('#v20-add-zh').value.trim();if(!validEnglish(en)){ $('#v20-add-error').textContent='請輸入可用英文；單字、詞組或句子都可以。';return;}v20History();v20Touch();const doc=V20.fromText(en,uid('manual'));const c=V20.candidates(V20.fromText(en+' | '+zh,doc.id),{mode:'list',dictionary:v20Dictionary,common:v20.common})[0];Object.assign(c,{en,zh,originalText:en,sourceText:en,reviewReasons:[],reviewed:true,selected:true,kind:kindOf(en),excludedReason:''});v20.documents.push(doc);v20.items.push(c);$('#v20-add-dialog').close();v20RenderWords();}
function v20Summary(){if(v20.rawDirty){toast('請先整理剛修改的原文。','bad');return;}if(!v20Selected().length)return;v20Dialog('3. 核對及加入','<div id="v20-summary-content"></div>','<button class="btn secondary" data-imp="close-dialog">繼續選字</button><button class="btn primary" data-act="save-range" id="v20-save-range">確認加入</button>','v20-summary');v20RenderSummary();}
function v20RenderSummary(){const box=$('#v20-summary-content');if(!box)return;const rows=v20Selected(),pend=v20Pending(),dup=rows.length-new Set(rows.map(c=>c.en+'\u0000'+c.zh)).size;const blocked=pend.length||rows.length>120||!rows.length||dup>0||v20.rawDirty;
 box.innerHTML=`<p><strong>${esc(importDraft.title||'英文默書')}</strong> · ${rows.length} 項</p>${blocked?`<p class="v20-review-notice">${rows.length>120?'每份最多 120 項，請取消部分選取。':pend.length?`尚有 ${pend.length} 項需逐項核對或略過。`:dup?'有完全相同的項目，請先返回選字頁合併。':'請先選取字詞。'}</p>`:'<p class="small muted">請最後對照原稿；沒有被辨認出的字，也可以返回補上。</p>'}<ul class="v20-summary-list">${rows.map(c=>`<li><span><strong lang="en">${esc(c.en)}</strong><small>${esc(c.zh||'未填中文')} · ${V20.pending(c)?'待核對':'可加入'}</small></span><button data-imp="edit" data-id="${esc(c.id)}">${V20.pending(c)?'核對':'修改'}</button><button data-imp="summary-remove" data-id="${esc(c.id)}" aria-label="略過 ${esc(c.en)}">略過</button></li>`).join('')}</ul><label class="v20-check v20-summary-check"><input type="checkbox" id="confirm-import" ${blocked?'disabled':''}>我已對照原稿，確認這些是今次默書範圍</label><p class="small muted">只加入上面的項目。不保存整張相片或未選內容；姓名及班別已預設不選。</p><div id="v20-save-error" role="alert"></div>`;
 const b=$('#v20-save-range');if(b)b.disabled=!!blocked||!$('#confirm-import').checked;}
function v20ValidateEvidence(p){if(!p||typeof p!=='object'||Array.isArray(p))throw Error('import evidence');const text=(v,max)=>{if(typeof v!=='string'||v.length>max||/[\u0000-\u0008\u000b\u000c]/.test(v))throw Error('import text');return v;};if(!['list','passage','sentences','manual'].includes(p.mode)||!Array.isArray(p.sources)||p.sources.length>10)throw Error('import source');return {version:1,mode:p.mode,checked:p.checked===true,sources:p.sources.map(s=>({original:text(s.original,240),context:text(s.context,500),region:text(s.region,100),boxes:(Array.isArray(s.boxes)?s.boxes:[]).slice(0,60).map(b=>{const z=window.WQImportCore.box(b);if(!z||Object.values(z).some(x=>x<0||x>50000))throw Error('import box');return z;})}))};}
saveRange=function(){if(v20.saving)return;captureImportDraft();const selected=v20Selected();const dup=selected.length-new Set(selected.map(c=>c.en+'\u0000'+c.zh)).size;if(!selected.length||selected.length>120||v20Pending().length||v20.rawDirty||dup||!$('#confirm-import')?.checked){v20RenderSummary();toast('請先核對已選項目，並勾選確認。','bad');return;}const bad=selected.find(c=>!validEnglish(c.en)||c.zh.length>300);if(bad){toast('「'+bad.en+'」格式需要修改。','bad');return;}const c=activeChild();if(!c||v20Origin&&v20Origin!==v20Owner()){toast('孩子或帳戶已切換，請重新確認匯入。','bad');return;}const title=importDraft.title.trim()||'英文默書';if(title.length>120){toast('名稱請用 120 字以內。','bad');return;}const before=structuredClone(db);v20.saving=true;
 try{const r={id:uid('r'),childId:c.id,title,dictationDate:importDraft.date,createdAt:new Date().toISOString()};db.ranges.push(r);for(const x of selected){const meta=V20.gloss(x.en,v20Dictionary),sources=[{original:x.originalText.slice(0,240),context:x.sourceText.slice(0,500),region:x.sourceRegionId,boxes:x.sourceBoxes},...(x.moreSources||[]).map(s=>({original:s.text.slice(0,240),context:s.sourceText.slice(0,500),region:s.regionId,boxes:s.boxes}))].slice(0,10);db.words.push({id:uid('w'),childId:c.id,rangeId:r.id,en:x.en,zh:x.zh,kind:x.kind,example:meta.choices.length===1&&meta.zh===x.zh?meta.example:'',emoji:'',createdAt:new Date().toISOString(),studySeen:0,reviewLevel:0,reviewDue:null,lastSeen:null,importEvidence:v20ValidateEvidence({mode:v20.mode,checked:true,sources})});}c.activeRangeId=r.id;db.session=null;if(!save()){db=before;$('#v20-save-error').innerHTML='<p class="v20-error">未能儲存。選詞及草稿仍在；請先備份，再重試。沒有顯示成功。</p>';return;}const wasLogged=isLoggedIn();clearImportDraft();mediaSelectedRange=r.id;mediaMessage='已加入你選定的默書內容。請核對圖片及準備讀音。';toast(wasLogged?'已儲存所選範圍。':'已加入試玩範圍；離開後不會保存。');go('offline');}
 catch(e){db=before;const el=$('#v20-save-error');if(el)el.innerHTML='<p class="v20-error">未能完成加入。原有教材沒有被取代，草稿仍在。</p>';}
 finally{v20.saving=false;}};
function v20RenderOriginal(){const cv=v20Photo?.original;if(!cv)return;const d=v20Dialog('原相','<img alt="原相" id="v20-original-image" style="width:100%;height:auto"><p class="small muted">查看有沒有漏辨認的區域；可返回「框選／拉直」再辨認。</p>','','v20-original');d.querySelector('img').src=v20Photo.originalURL;}
function v20DrawWorking(){const p=v20Photo;if(!p)return;const a=(p.turn+p.angle)*Math.PI/180,w=p.original.width,h=p.original.height;const cw=Math.ceil(Math.abs(w*Math.cos(a))+Math.abs(h*Math.sin(a))),ch=Math.ceil(Math.abs(h*Math.cos(a))+Math.abs(w*Math.sin(a)));const cv=document.createElement('canvas');cv.width=cw;cv.height=ch;const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cw,ch);ctx.translate(cw/2,ch/2);ctx.rotate(a);ctx.drawImage(p.original,-w/2,-h/2);p.working=cv;if(p.workingURL)URL.revokeObjectURL(p.workingURL);p.workingURL=cv.toDataURL('image/png');}
setOcrFile=async function(file,source='upload'){if(!file)return;if(file.size>20*1024*1024){toast('相片超過 20 MB，請縮小後再上傳。','bad');return;}if(!/^image\//i.test(file.type)||/svg/i.test(file.type)){toast('請選擇 JPG、PNG 或其他可讀取的相片，不接受 SVG。','bad');return;}cancelOCR();const epoch=++v20PhotoEpoch;v20FileLoading=true;const url=URL.createObjectURL(file);const im=new Image();try{await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url;});if(epoch!==v20PhotoEpoch)return;if(im.naturalWidth*im.naturalHeight>40000000)throw Error('圖片像素太大，請先縮小。');const scale=Math.min(1,2800/Math.max(im.naturalWidth,im.naturalHeight));const cv=document.createElement('canvas');cv.width=Math.round(im.naturalWidth*scale);cv.height=Math.round(im.naturalHeight*scale);const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(im,0,0,cv.width,cv.height);if(v20Photo?.originalURL)URL.revokeObjectURL(v20Photo.originalURL);v20Photo={id:uid('photo'),original:cv,originalURL:url,working:cv,workingURL:'',turn:0,angle:0,crop:{left:0,top:0,right:1,bottom:1},width:cv.width,height:cv.height};v20DrawWorking();if(ocrPreviewUrl)URL.revokeObjectURL(ocrPreviewUrl);ocrPreviewUrl=v20Photo.workingURL;ocrSelectedFile=file;importDraft.source=source;importDraft.fileName=file.name;v20.message=v20.items.length?'新相片已準備好。新辨認結果只會加在後面，不會蓋掉你已改的字。':'可先框選要默的部分，再辨認。';v20Origin=v20Owner();updateImportPhoto();}
 catch(e){URL.revokeObjectURL(url);if(epoch===v20PhotoEpoch)toast('相片讀不到或太大。請改用 JPG／PNG，或直接貼上文字。','bad');}
 finally{if(epoch!==v20PhotoEpoch){URL.revokeObjectURL(url);return;}v20FileLoading=false;updateImportPhoto();v20RenderWords();}};
updateImportPhoto=function(){const im=$('#ocr-preview'),name=$('#ocr-file-name'),run=$('#run-ocr');if(im){im.hidden=!v20Photo;if(v20Photo)im.src=v20Photo.workingURL;}if(name)name.textContent=importDraft.fileName?(importDraft.source==='camera'?'已拍攝：':'已選擇：')+importDraft.fileName:'未選擇圖片';if(run)run.disabled=!v20Photo||ocrBusy||v20FileLoading;const tools=$('#v20-photo-tools');if(tools)tools.hidden=!v20Photo;const cancel=$('#v20-cancel-ocr');if(cancel)cancel.hidden=!ocrBusy;};
function v20Crop(){if(!v20Photo)return;v20Origin=v20Owner();const p=v20Photo;const body=`<p class="small muted">先點左上角，再點右下角。只辨認橙框內；左右兩欄可分兩次加入。</p><div class="v20-crop-stage" id="v20-crop-stage"><canvas id="v20-crop-canvas"></canvas><div class="v20-crop-frame" id="v20-crop-frame"></div></div><div id="v20-crop-status" class="v20-inline-status" role="status">先點範圍的左上角。</div><div class="v20-crop-values">${[['left','左'],['top','上'],['right','右'],['bottom','下']].map(([k,t])=>`<label>${t}邊界 %<input type="number" min="0" max="100" step="1" data-crop-edge="${k}" value="${Math.round(p.crop[k]*100)}"></label>`).join('')}</div><div class="v20-toolbar"><button class="btn secondary" data-imp="rotate" data-value="-90">左轉 90°</button><button class="btn secondary" data-imp="rotate" data-value="90">右轉 90°</button><button class="btn quiet" data-imp="crop-reset">用整張相</button></div><label class="v20-rotation">微調傾斜<input id="v20-angle" type="range" min="-10" max="10" step="0.5" value="${p.angle}"><output id="v20-angle-value">${p.angle}°</output></label><p class="small muted">大幅透視變形或反光，請平放紙張再拍；這裏只作框選及旋轉，不會補回看不見的字。</p>`;v20Dialog('框選／拉直相片',body,'<button class="btn primary" data-imp="crop-done">用這個範圍</button>','v20-crop');v20CropPaint();let first=null;$('#v20-crop-stage').addEventListener('pointerup',e=>{if(e.button!==0&&e.pointerType==='mouse')return;const el=$('#v20-crop-canvas'),r=el.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));if(!first){first={x,y};$('#v20-crop-status').textContent='再點右下角。';}else{const left=Math.min(first.x,x),top=Math.min(first.y,y),right=Math.max(first.x,x),bottom=Math.max(first.y,y);if(right-left<.015||bottom-top<.015){$('#v20-crop-status').textContent='範圍太小，請重新點左上角。';first=null;return;}p.crop={left,top,right,bottom};first=null;v20PhotoEpoch++;cancelOCR();v20CropPaint();$('#v20-crop-status').textContent='已選好。可以再點兩個角重新選取。';}});}
function v20CropPaint(){if(!v20Photo)return;const cv=$('#v20-crop-canvas'),p=v20Photo;if(cv){const h=Math.min(460,window.innerHeight*.4),scale=Math.min(1,420/p.working.width,h/p.working.height);cv.width=Math.round(p.working.width*scale);cv.height=Math.round(p.working.height*scale);$('#v20-crop-stage').style.maxWidth=cv.width+'px';cv.getContext('2d').drawImage(p.working,0,0,cv.width,cv.height);}const f=$('#v20-crop-frame');if(f){const c=p.crop;Object.assign(f.style,{left:c.left*100+'%',top:c.top*100+'%',width:(c.right-c.left)*100+'%',height:(c.bottom-c.top)*100+'%'});$$('[data-crop-edge]').forEach(i=>i.value=Math.round(c[i.dataset.cropEdge]*100));}updateImportPhoto();}
function v20ProcessPhoto(){const p=v20Photo;if(!p)throw Error('未有相片');const c=p.crop;if(c.left>=c.right||c.top>=c.bottom)throw Error('框選範圍不正確，請調整四個邊界。');const x=Math.floor(p.working.width*c.left),y=Math.floor(p.working.height*c.top),w=Math.max(1,Math.floor(p.working.width*(c.right-c.left))),h=Math.max(1,Math.floor(p.working.height*(c.bottom-c.top)));const sc=Math.min(2,Math.max(1,1300/Math.max(w,h))),pad=16;const canvas=document.createElement('canvas');canvas.width=Math.round(w*sc)+2*pad;canvas.height=Math.round(h*sc)+2*pad;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(p.working,x,y,w,h,pad,pad,w*sc,h*sc);if($('#v20-enhance')?.checked){const data=ctx.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<data.data.length;i+=4){const val=.299*data.data[i]+.587*data.data[i+1]+.114*data.data[i+2],v=Math.max(0,Math.min(255,(val-128)*1.12+128));data.data[i]=data.data[i+1]=data.data[i+2]=v;}ctx.putImageData(data,0,0);}return canvas;}
runOCR=async function(){if(!v20Photo||ocrBusy||v20FileLoading)return;if(v20.rawDirty){toast('你剛修改了原文，請先整理文字再辨認其他範圍。','bad');return;}if(v20.documents.length>=12){toast('已加入多個範圍，請先完成這份教材，再加入下一份。','bad');return;}if(v20.items.length&&!confirm('保留你已選及修改的字詞，將這次辨認加在後面？'))return;captureImportDraft();v20Origin=v20Owner();const owner=v20Owner(),photoId=v20Photo.id,epoch=v20PhotoEpoch,rev=v20.revision,psm=$('#v20-psm')?.value||'3',job=++ocrJob;let image;try{image=v20ProcessPhoto();}catch(e){toast(e.message,'bad');return;}ocrBusy=true;updateOCR('正在準備辨認；未完成前不會更改你的選詞。',4);updateImportPhoto();v20RenderWords();let worker=null,timer=null;const valid=()=>job===ocrJob&&photoId===v20Photo?.id&&epoch===v20PhotoEpoch&&rev===v20.revision&&owner===v20Owner()&&lastRoute==='range-new';
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('辨認逾時，請縮小範圍後再試。')),90000);});
 try{const result=await Promise.race([(async()=>{await loadTesseract();if(!valid())return null;if(!window.Tesseract?.createWorker)throw Error('辨認元件未載入');const logger=m=>{if(valid()){const percent=m.status==='recognizing text'?Math.round((m.progress||0)*100):10;updateOCR(m.status==='recognizing text'?`正在辨認 ${percent}%`:'正在載入英文辨認資料…',percent);}};worker=await Tesseract.createWorker('eng',1,{logger,errorHandler:()=>{}});if(!valid()){await worker.terminate();return null;}activeOcrWorker=worker;await worker.setParameters({tessedit_pageseg_mode:psm,preserve_interword_spaces:'1',user_defined_dpi:'300'});return await worker.recognize(image,{}, {text:true,blocks:true,tsv:true,hocr:false,pdf:false});})(),timeout]);if(!valid()||!result)return;const doc=V20.fromOCR(result.data,uid('ocr'));const items=V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common});if(v20.items.length+items.length>1500)throw Error('內容太多，請框選較小的範圍。');if(!items.length){updateOCR('這個範圍未辨認到英文。請看原相，重新框選或手動補字。',0);return;}const blob=await new Promise(resolve=>image.toBlob(resolve,'image/png'));if(!valid())return;if(blob){doc.previewURL=URL.createObjectURL(blob);doc.width=image.width;doc.height=image.height;}doc.engineText=String(result.data.text||'').slice(0,30000);v20History();v20.documents.push(doc);v20.items.push(...items);v20.revision++;v20.parsedRaw=v20.documents.map(d=>d.raw).join('\n\n');importDraft.raw=v20.parsedRaw;$('#raw-words').value=importDraft.raw;v20.rawDirty=false;v20.filter='all';v20.message=doc.warnings.length?doc.warnings.join(' '):'已分成可點選項目。仍請核對錯字及漏字；選取後才會加入教材。';updateOCR(`已辨認 ${items.length} 個候選項目，請對照原稿。`,100);v20RenderWords();}
 catch(e){if(valid())updateOCR(navigator.onLine?(e.message||'暫時未能辨認，請重試或貼上文字。'):'目前離線，辨認元件或英文資料未準備好。仍可貼文字及選字。',0);}
 finally{clearTimeout(timer);if(worker)try{await worker.terminate();}catch(_){}if(activeOcrWorker===worker)activeOcrWorker=null;if(job===ocrJob){ocrBusy=false;updateImportPhoto();v20RenderWords();}}};
applyOCR=function(payload){const doc=typeof payload==='string'?V20.fromText(payload,uid('ocrtext')):V20.fromOCR(payload,uid('ocr'));v20History();v20Touch();v20.documents.push(doc);v20.items.push(...V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common}));v20.parsedRaw=v20.documents.map(d=>d.raw).join('\n\n');importDraft.raw=v20.parsedRaw;if($('#raw-words'))$('#raw-words').value=importDraft.raw;v20.rawDirty=false;v20RenderWords();};
function v20CommonDialog(){const terms=[...new Set(v20.items.filter(c=>!c.en.includes(' ')&&c.kind!=='sentence').map(c=>V20.fold(c.en)))].sort();v20Dialog('今次哪些字放常用字？','<p class="small muted">只改分組，不會改選取，也不代表孩子已學會。</p><div class="v20-common-editor">'+terms.map(t=>`<label><input type="checkbox" data-common="${esc(t)}" ${v20.common.has(t)?'checked':''}>${esc(t)}</label>`).join('')+'</div>','<button class="btn primary" data-imp="save-common">儲存今次分組</button>','v20-common-dialog');}
function v20Click(e){const b=e.target.closest('[data-imp]');if(!b||b.disabled)return;const a=b.dataset.imp,id=b.dataset.id,c=v20.items.find(x=>x.id===id);try{
 if(a==='close-dialog'){b.closest('dialog')?.close();return;}
 if(a==='parse')v20Parse();if(a==='mode')v20ChangeMode(b.dataset.value);if(a==='filter'){v20.filter=b.dataset.value;v20.showLimit=120;v20RenderWords();}if(a==='more'){v20.showLimit+=120;v20RenderWords();}
 if(a==='toggle'&&c){if(v20.mergeMode){if(!v20.mergeStart){v20.mergeStart=c.id;v20RenderWords();return;}const merged=V20.merge(v20.items,v20.mergeStart,c.id,uid('merged'));v20History();v20Touch();v20.items=merged;v20.items.forEach(v20Recheck);v20.mergeMode=false;v20.mergeStart=null;v20RenderWords();return;}v20History();v20Touch();c.selected=!c.selected;if(c.selected&&c.excludedReason){c.reviewReasons=['請確認這不是頁首或個人資料'];c.reviewed=false;}v20RenderWords();}
 if(a==='edit'&&c)v20Edit(id);if(a==='save-edit')v20SaveEdit(id);if(a==='suggest'){$('#v20-edit-en').value=b.dataset.value;const g=V20.gloss(b.dataset.value,v20Dictionary);$('#v20-edit-zh').value=g.zh;$('#v20-item-checked').checked=false;}if(a==='meaning'){$('#v20-edit-zh').value=b.dataset.value;$('#v20-item-checked').checked=false;}
 if(a==='split'&&c){const children=V20.split(c,uid('split')).map(v20Recheck);v20History();v20Touch();const i=v20.items.indexOf(c);v20.items.splice(i,1,...children);$('#v20-edit-dialog').close();v20RenderWords();if($('#v20-summary'))v20RenderSummary();}
 if(a==='merge-mode'){v20.mergeMode=!v20.mergeMode;v20.mergeStart=null;v20RenderWords();}
 if(['select-all','select-none','skip-common','select-common'].includes(a)){v20History();v20Touch();v20.items.forEach(c=>{if(c.excludedReason&&!c.selected)return;if(a==='select-all')c.selected=true;if(a==='select-none')c.selected=false;if(v20.mode==='passage'&&c.common){if(a==='skip-common')c.selected=false;if(a==='select-common')c.selected=true;}});v20.message=a==='skip-common'?'已略過常用字；原文及詞組保持不變。':'';v20RenderWords();}
 if(a==='restore'&&c){v20History();v20Touch();c.selected=true;c.reviewed=false;c.reviewReasons=['請確認這不是頁首或個人資料'];v20RenderWords();v20Edit(c.id);}
 if(a==='summary')v20Summary();if(a==='summary-remove'&&c){v20History();v20Touch();c.selected=false;v20RenderWords();v20RenderSummary();}
 if(a==='dedupe'){v20History();v20Touch();const r=V20.deduplicate(v20.items);v20.items=r.items;v20.message=`已合併 ${r.count} 個完全相同的項目，原來的出現位置仍保留。`;v20RenderWords();}
 if(a==='undo')v20Undo();if(a==='add')v20Add();if(a==='save-add')v20SaveAdd();if(a==='edit-common')v20CommonDialog();if(a==='save-common'){v20History();v20Touch();$$('[data-common]').forEach(i=>i.checked?v20.common.add(i.dataset.common):v20.common.delete(i.dataset.common));v20.items.forEach(c=>c.common=v20.common.has(V20.fold(c.en))&&!/\s/.test(c.en)&&c.kind!=='sentence');$('#v20-common-dialog').close();v20RenderWords();}
 if(a==='crop')v20Crop();if(a==='full-photo')v20RenderOriginal();if(a==='crop-done'){const p=v20Photo;if(!p||p.crop.left>=p.crop.right||p.crop.top>=p.crop.bottom){toast('範圍的右及下邊界要大於左及上邊界。','bad');return;}$('#v20-crop').close();v20.message='已框選。按「辨認所選範圍」加入候選字詞。';v20RenderWords();}
 if(a==='crop-reset'&&v20Photo){v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20CropPaint();}if(a==='rotate'&&v20Photo){v20Photo.turn=(v20Photo.turn+Number(b.dataset.value)+360)%360;v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20DrawWorking();v20CropPaint();}
 if(a==='cancel-ocr'){cancelOCR();updateOCR('已停止辨認。原有選詞及更正仍然保留。',0);updateImportPhoto();v20RenderWords();}
 }catch(err){toast(err.message||'未完成操作，原有資料仍保留。','bad');}}
document.addEventListener('click',v20Click);
/* Catch original source edits before the legacy listener which cleared every draft row. */
document.addEventListener('input',e=>{if(e.target.id==='raw-words'){e.stopImmediatePropagation();cancelOCR();importDraft.raw=e.target.value;v20.rawDirty=importDraft.raw!==v20.parsedRaw;v20.revision++;importDraft.confirmed=false;v20RenderWords();updateImportPhoto();}if(e.target.matches?.('[data-crop-edge]')&&v20Photo){const v=Number(e.target.value)/100;if(Number.isFinite(v)&&v>=0&&v<=1){v20Photo.crop[e.target.dataset.cropEdge]=v;v20PhotoEpoch++;cancelOCR();const f=$('#v20-crop-frame'),c=v20Photo.crop;if(f)Object.assign(f.style,{left:c.left*100+'%',top:c.top*100+'%',width:Math.max(0,c.right-c.left)*100+'%',height:Math.max(0,c.bottom-c.top)*100+'%'});}}if(e.target.id==='v20-angle'&&v20Photo){v20Photo.angle=Number(e.target.value);v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20DrawWorking();v20CropPaint();$('#v20-angle-value').textContent=v20Photo.angle+'°';}},true);
document.addEventListener('change',e=>{if(e.target.id==='confirm-import'&&$('#v20-summary')){importDraft.confirmed=e.target.checked;$('#v20-save-range').disabled=!e.target.checked||v20Pending().length>0||v20Selected().length>120;}});
const v20PrevRender=render;render=function(){const route=(location.hash||'#kid').slice(1).split('?')[0];if(route!=='range-new')v20CloseAll();v20PrevRender();document.body.classList.toggle('import-selection-active',route==='range-new');if(route==='range-new'&&!v20Origin)v20Origin=v20Owner();};
window.addEventListener('pagehide',()=>cancelOCR());
/* Read-only diagnostic metadata. Tests attach their own state hook before startup. */
window.__WQ_IMPORT_V20__=Object.freeze({version:V20.VERSION,dictionarySize:v20Dictionary.size,sourceFormat:'blocks-lines-words / TSV / text',limits:{items:1500,selected:120,regions:12},draftPolicy:'memory-only',count:()=>({all:v20.items.length,selected:v20Selected().length,review:v20Pending().length})});

const v20OriginalToast=toast;toast=function(message,type='ok'){if(lastRoute!=='range-new'||!$('#import-v20'))return v20OriginalToast(message,type);v20.message=message;const dialog=[...document.querySelectorAll('.v20-dialog[open]')].at(-1);if(dialog){let status=dialog.querySelector('.v20-dialog-notice');if(!status){status=document.createElement('p');status.className='v20-dialog-notice';status.setAttribute('role','status');dialog.querySelector('.v20-dialog-body').prepend(status);}status.className='v20-dialog-notice '+(type==='bad'?'v20-error':'v20-review-notice');status.textContent=message;}else{const status=$('#v20-message');if(status){status.textContent=message;status.setAttribute('role',type==='bad'?'alert':'status');}}};



/* V21 test admin integration. It is intentionally not a protected staff portal.
   Role is derived from the reserved session ID, never a user-supplied backup role/name. */
async function loginTestAdmin(){
 if(!WQ_TEST_MODE){toast('標準版沒有公開管理員。','bad');return;}
 if(authBusy)return;const pin=$('#login-pin')?.value||'';if(!/^\d{4}$/.test(pin)){toast('帳戶名稱或 PIN 不正確。','bad');return;}
 authBusy=true;let previous='';let wroteSession=false;
 try{
  const hash=await pinHash(pin,TEST_ADMIN.salt),expected=globalThis.crypto?.subtle?TEST_ADMIN.hash:TEST_ADMIN.legacyHash;
  if(hash!==expected){toast('帳戶名稱或 PIN 不正確。','bad');return;}
  previous=sessionStorage.getItem(SESSIONKEY)||'';
  // Verify both storage mechanisms before switching accounts. Do not overwrite existing data.
  const probe='wordquest-v21-storage-probe';localStorage.setItem(probe,'1');localStorage.removeItem(probe);
  sessionStorage.setItem(SESSIONKEY,TEST_ADMIN.id);wroteSession=true;
  stopSpeech();pcStop();fgStopAudio();clearImportDraft();loadBlocked=false;persistenceIssue='';
  db=load();if(!await arAcquire())throw Error('另一分頁正在編輯。');if(!loadBlocked&&!save())throw Error('storage');
  toast('已登入 Admin 測試帳號。');go('admin');render();
 }catch(e){
  if(wroteSession){try{if(previous)sessionStorage.setItem(SESSIONKEY,previous);else sessionStorage.removeItem(SESSIONKEY);}catch(_){}loadBlocked=false;db=load();}
  toast('未能登入測試帳號，請允許此網站使用瀏覽器儲存。','bad');
 }finally{authBusy=false;}
}
function adminButton(text,action,extra='',cls='secondary'){return `<button type="button" class="btn ${cls}" data-admin="${action}" ${extra}>${esc(text)}</button>`;}
function adminView(){
 if(!isTestAdmin())return `<section class="card pad"><h1>管理員測試</h1><p>請先使用管理員測試帳號登入。</p>${link('前往登入','login','primary')}</section>`;
 return `<section class="admin-dashboard"><div class="row between"><div><p class="eyebrow">WORDQUEST V21 · 測試專用</p><h1>Admin 測試中心</h1></div>${link('返回學生首頁','kid','secondary')}</div>
 <div class="notice"><strong>只管理這個瀏覽器的測試資料。</strong>不是雲端管理員，不會看到朋友的帳戶或答題紀錄。請用暱稱及去掉個人資料的默書紙。</div>
 <section class="card pad admin-mode"><div><h2>${adminUnlocks()?'全部開放':'按一般規則測試'}</h2><p>${adminUnlocks()?'十二課可直接做小測，六款遊戲及三種難度可免費測試。解鎖不代表學過或答對。':'課後小測須先學完；遊戲照常扣測試帳戶的金幣。切回全部開放不改成績。'}</p></div>${adminButton(adminUnlocks()?'改用一般規則':'開放全部功能','toggle','','primary')}</section>
 <div class="admin-cards"><section class="card pad"><h2>教材及學習</h2><div class="admin-links">${link('拍照／上傳及點選字詞','range-new')}${link('全部默書範圍','ranges')}${link('所有題型','practice')}${link('air 拼字家族','spelling-family')}${link('離線圖片及讀音','offline')}${link('孩子資料','children')}${link('學習報告','report')}${link('聲效、設定及備份','settings')}</div></section>
 <section class="card pad"><h2>遊戲測試</h2><p class="small muted">先選難度，再選遊戲；切換遊戲會結束上一張測試票。仍保留 1–3 分鐘時限。</p><label for="admin-level">挑戰程度</label><select id="admin-level">${['入門','標準','挑戰'].map((n,i)=>`<option value="${i}" ${arcPrefs().level===i?'selected':''}>${n}</option>`).join('')}</select><div class="admin-links">${Object.values(ARC.spec).filter(g=>g.id!=='shooter').map(g=>adminButton(g.name,'game',`data-game="${g.id}"`)).join('')}</div>${link('到挑戰區看玩法','game','soft')}</section></div>
 <section class="card pad admin-courses"><h2>拼字專家 · 十二課</h2><p class="small muted">已聽讀音、跟讀和答題結果按實際操作記錄，不會因管理員權限而自動填滿。</p><div class="admin-lessons">${PC.lessons.map(l=>`<article><strong>${l.number} · ${esc(l.pattern)}</strong><span>${esc(l.title)}</span><div>${pcBtn('看教學','learn',`data-lesson="${l.id}"`,'secondary')}${pcBtn('課後小測','quiz',`data-lesson="${l.id}" ${pcReadyToTest(l.id)?'':'disabled'}`,'primary')}</div></article>`).join('')}</div></section>
 <details class="card pad admin-reset"><summary>重新開始測試</summary><p>重設只清除 Admin 的教材文字、成績、金幣及遊戲票；不清除其他本機帳戶。自備圖片／音檔另在離線教材管理。</p>${adminButton('重設 Admin 測試資料','reset','','danger')}${link('先匯出備份','settings','secondary')}</details></section>`;
}
const adminPriorLoginView=loginView;loginView=function(){return adminPriorLoginView()+(!isLoggedIn()?'<p class="small muted admin-login-note">本機家庭試用：可自建帳戶；不要使用真名或其他網站的密碼。測試管理員使用預設 Admin 帳號。</p>':'');};
const adminPriorRender=render;
render=function(){
 adminPriorRender();
 document.body.classList.toggle('admin-test-session',isTestAdmin());
 const brand=$('.brand');if(brand){brand.href=isTestAdmin()?'#admin':'#kid';brand.title=isTestAdmin()?'Admin 測試中心':'WordQuest 學生首頁';const name=brand.querySelector('span:last-child');if(name)name.textContent=isTestAdmin()?'Admin':'WordQuest';}
 if(lastRoute==='admin'){$('#app').innerHTML=adminView();document.body.classList.remove('quiz-active','arcade-active','phonics-active','family-active','import-selection-active');}
 if(isTestAdmin()&&['kid','parent','game','phonics','report'].includes(lastRoute)){
  const b=document.createElement('p');b.className='notice admin-state';b.textContent=adminUnlocks()?'Admin 測試中：功能全開；遊戲免費。紀錄只屬本機測試，不是朋友的成績。':'Admin 一般規則：按正常學習及扣幣流程測試。';$('#app').prepend(b);
 }
 const f=document.querySelector('.footer');if(f)f.firstChild && (f.firstChild.nodeType===3) && (f.firstChild.textContent='WordQuest V28 街機版 · 帳戶、金幣及紀錄只存於這個瀏覽器，沒有雲端同步。勿輸入敏感個人資料。 ');
 updateViewport();
};
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-admin]');if(!b||b.disabled)return;if(!isTestAdmin()){go('login');return;}
 if(b.dataset.admin==='toggle'){
  arPause();arEngine=null;
  // A free test ticket must never be usable after switching to normal rules.
  if(adminUnlocks()){const t=arcTicket();if(t?.testOnly&&t.status==='open'){const old=structuredClone(db);t.status='finished';t.remainingMs=0;if(!save()){db=old;return;}}}
  try{sessionStorage.setItem('wordquest-v29-admin-rules',adminUnlocks()?'normal':'unlocked');}catch(_){toast('未能更改測試方式。','bad');return;}
  render();
 }
 if(b.dataset.admin==='game'){
  const level=Number($('#admin-level')?.value);if([0,1,2].includes(level)){const old=arcPrefs().level;arcPrefs().level=level;if(!save()){arcPrefs().level=old;return;}}
  arIntro(b.dataset.game);
 }
 if(b.dataset.admin==='reset'){arPause();resetAll();if(lastRoute==='parent')go('admin');}
});
// Enter in PIN inputs submits the intended form, never creates an account implicitly.
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&!e.repeat&&e.target.id==='login-pin'){e.preventDefault();loginAccount();}});
window.__WQ_ADMIN_INFO__=Object.freeze({version:21,localTestOnly:true,active:()=>isTestAdmin(),unlocked:()=>adminUnlocks()});

/* Appended INSIDE the existing WordQuest app closure. V21 remains the host. */
const PG=window.WQRewards;
let pgGame=null,pgMeta=null,pgPlaying=false,pgBusy=false,pgFrame=0,pgLast=0,pgAcc=0,pgReason='ready',pgOwner='',pgTools=[],pgHint='',pgResult=null,pgFree=false,pgSlot='',pgError='',pgFilter='已開放';
const pgThumbCache=new Map();
function pgRoot(){return db.playgroundV22||(db.playgroundV22=PG.initial('legacy'));}
function pgChild(){return PG.get(pgRoot(),activeChild().id);}
function pgDay(){return today();}
function pgTime(ms){return arFmt(Math.max(0,ms));}
function pgAllow(id){return isLoggedIn()&&PG.allowed(pgChild(),id,adminUnlocks());}
function pgButton(label,action,extra='',style='secondary'){return `<button type="button" class="btn ${style}" data-pg="${action}" ${extra}>${label}</button>`;}
function pgInfo(){const c=pgChild(),n=PG.count(c),next=[5,15,30,50].find(v=>n<v);return{c,n,next};}
function pgLegacy(){return Object.values(ARC.spec).filter(g=>g.id!=='shooter');}
function pgLobby(){const {c,n,next}=pgInfo(),t=c.ticket,open=PG.catalog.filter(g=>pgAllow(g.id)).length;
return `<section class="pg-lobby"><div class="pg-hero"><div><p class="eyebrow">WORDQUEST · 學一小段，玩一會</p><h1>你的遊戲小天地</h1><p>用金幣換時間。重試、換遊戲，都不會再扣幣。</p><div class="row"><span class="chip">已通過複習 <b>${n}</b> 個學習項目</span><span class="chip">${open} / 20 款已開放</span></div></div><div class="pg-wallet"><span>可用金幣</span><strong>★ ${isLoggedIn()?activeChild().stars:0}</strong><small>${adminUnlocks()?'Admin 免費測試，不改正常存檔':'5 星 / 90 秒 · 10 星 / 3 分鐘'}</small></div></div>
${!isLoggedIn()?`<div class="notice">訪客可以先學習；登入本機帳戶後才保存金幣及遊戲進度。${link('登入／建立帳戶','login','primary')}</div>`:''}
${t?.remainingMs>0?`<section class="pg-resume card pad"><div><h2>還有 ${pgTime(t.remainingMs)} 可以玩</h2><p class="muted">已付款時間，重開或轉遊戲都不用再買。</p></div><div class="row">${pgButton('繼續遊玩','intro',`data-id="${t.last}"`,'primary')}${t.usedMs===0&&!t.refunded&&t.cost>0?pgButton('取消未用時段 · 退 '+t.cost+' 星','refund',`data-receipt="${esc(t.id)}"`,'quiet'):''}</div></section>`:''}
<div class="pg-progress card pad"><div><strong>${next?`再有 ${Math.max(0,next-n)} 個學習項目通過複習，開放下一組遊戲`:'20 款遊戲的字數門檻全部達成'}</strong><p class="small muted">獨立串對後，至少相隔 24 小時、不剛看答案，再串對才計入。花星不會減少字數。</p></div><div class="bar"><span style="width:${Math.min(100,n/50*100)}%"></span></div><span class="small">今日已玩 ${pgTime(PG.day(c,pgDay()).usedMs)} ／ ${c.limit} 分鐘（包括原有遊戲）</span></div>
<div class="pg-tabs" role="group" aria-label="遊戲分類">${['全部','已開放','動作','運動','解謎','策略','創作'].map(f=>pgButton(f,'filter',`data-filter="${f}" aria-pressed="${pgFilter===f}"`,pgFilter===f?'primary':'soft')).join('')}</div><div class="pg-grid">${PG.catalog.filter(p=>{const g=WQGames.find(g=>g.id===p.id);return pgFilter==='全部'||pgFilter==='已開放'&&(pgAllow(p.id)||!isLoggedIn()&&p.words===0)||g.category===pgFilter;}).map(p=>{const g=WQGames.find(g=>g.id===p.id),yes=pgAllow(p.id);return `<article class="pg-card ${yes?'':'pg-locked'}"><div class="pg-art" data-pgthumb="${g.id}" aria-hidden="true"></div><div class="pg-cardbody"><div class="eyebrow">${g.tag} · ${g.category}</div><h2>${g.name}</h2><p>${g.desc}</p><div class="pg-cardfoot"><span>${yes?adminUnlocks()?'測試免費':`${p.cost} 幣 / ${p.seconds===90?'90 秒':'3 分鐘'}`:c.override[g.id]==='blocked'?'家長暫停開放':`${p.words} 個學習項目解鎖`}</span>${pgButton(yes?'看看玩法':'了解解鎖','intro',`data-id="${g.id}"`,yes?'primary':'soft')}</div></div></article>`;}).join('')}</div>
<details class="card pad pg-legacy"><summary><strong>原有 5 款非暴力遊戲</strong> · 舊設定與紀錄保留</summary><p class="small muted">維持原本金幣價格及每次 ${db.settings.gameMinutes} 分鐘；每日上限與新遊戲共用。原有遊戲票可繼續。</p><div class="row">${pgLegacy().map(g=>arButton(g.name,'intro',`data-game="${g.id}"`,'soft')).join('')}</div>${arcTicket()?.status==='open'&&arcTicket()?.game!=='shooter'?arButton('繼續原有遊戲票','resume','','primary'):''}${arcTicket()?.status==='open'&&arcTicket()?.game==='shooter'?`<div class="notice">射擊遊戲已停用，舊紀錄保留。可免費將未用時間轉入新遊戲。${pgButton('轉移未用時間','transfer')}</div>`:''}</details><p class="small muted">本機保存，沒有雲端同步。${link('家長遊戲設定','game-settings','quiet')} ${link('返回學習','kid','quiet')}</p></section>`;}
function pgSettingsView(){if(!isLoggedIn())return loginView();const c=pgChild(),n=PG.count(c),d=PG.day(c,pgDay());return `${navTabs('settings')}<section class="card pad"><p class="eyebrow">${esc(activeChild().name)} · 家長設定</p><h1>金幣與遊戲</h1><div class="notice">這是本機家庭設定，並非安全家長鎖或雲端帳戶；不要視為防止孩子修改數據的保護。</div><div class="grid2"><div class="field"><label for="pg-limit">每日遊戲上限（新舊合計）</label><select id="pg-limit">${[0,3,6,9,15,30,60].map(v=>`<option value="${v}" ${c.limit===v?'selected':''}>${v===0?'暫停遊戲':v+' 分鐘'}</option>`).join('')}</select></div><div class="field"><label for="pg-mode">主站練習派星方式（此帳戶）</label><select id="pg-mode"><option value="legacy" ${pgRoot().mode==='legacy'?'selected':''}>保留原有：原本答題及完成獎勵</option><option value="balanced" ${pgRoot().mode==='balanced'?'selected':''}>平衡版：無提示答對 1 星、完成訂正 +5</option></select></div></div><p class="small muted">平衡版：主站練習每日最多 30 星；同字同題型每日只派一次。拼字家族及 12 堂拼音課維持原本獎勵，不在這 30 星之內。舊餘額不改動。新遊戲價格固定為 5 星／90 秒、10 星／3 分鐘。</p><div class="field"><label for="pg-difficulty">新遊戲挑戰程度</label><select id="pg-difficulty">${['入門','標準','挑戰'].map((v,i)=>`<option value="${i}" ${c.difficulty===i?'selected':''}>${v}</option>`).join('')}</select></div><details style="margin:20px 0"><summary><strong>逐款遊戲權限</strong></summary><p>提前開放只改遊戲權限，不增加「通過複習」字數。已通過的關卡仍會保存。</p><div class="pg-permissions">${PG.catalog.map(g=>`<label>${WQGames.find(m=>m.id===g.id).name}<select data-pgpermission="${g.id}"><option value="auto" ${!c.override[g.id]?'selected':''}>按字數（${g.words} 字）</option><option value="open" ${c.override[g.id]==='open'?'selected':''}>提前開放</option><option value="blocked" ${c.override[g.id]==='blocked'?'selected':''}>暫停開放</option></select></label>`).join('')}</div></details>${pgButton('儲存遊戲設定','save-settings','','primary')} ${link('返回遊戲','game','soft')}<hr><h2>紀錄</h2><p>可用 ${activeChild().stars} 幣 · 通過複習 ${n} 字 · 今日主站平衡獎勵 ${d.earned} 幣</p><details><summary>查看通過複習的字</summary><p>${Object.entries(c.evidence).filter(([,e])=>e.qualifiedAt>0).map(([w])=>esc(w)).join('、')||'未有新制複習紀錄。舊有成績沒有刪除，但不會當成已完成延後回想。'}</p></details><details><summary>最近 10 筆換領紀錄</summary><ul class="list">${c.sessions.slice(-10).reverse().map(r=>`<li><span>${esc(r.date)} · ${r.durationMs/1000} 秒</span><strong>${r.refunded?'已退回':`−${r.cost} 幣`}</strong></li>`).join('')||'<li>未有換領紀錄。</li>'}</ul></details><p class="small muted">遊戲棋盤、時間及解鎖會隨原有「設定／備份」匯出；圖片和英式音檔仍使用原有教材包。</p></section>`;}
function pgPlayView(){if(!pgGame||pgOwner!==accountId()+':'+activeChild().id)return `<section class="card pad"><h1>繼續你的小休息</h1><p>從遊戲大廳選擇遊戲，讀取已付款時間及存檔。</p>${link('前往遊戲大廳','game','primary')}</section>`;return `<section class="pg-play"><div class="pg-playhead"><div><p class="eyebrow">${pgFree?'ADMIN · 獨立測試':'遊戲小天地'}</p><h1>${pgMeta.name}</h1></div><strong id="pg-clock" role="timer">${pgFree?'測試不限時':pgTime(pgChild().ticket?.remainingMs||0)}</strong></div><div class="pg-viewport"><canvas id="pg-canvas" width="800" height="560" tabindex="0" aria-label="${pgMeta.name}遊戲畫面"></canvas><div id="pg-overlay" class="pg-overlay"></div></div><div class="pg-controls">${pgMeta.keys.map(([k,l])=>`<button class="btn soft pg-key" data-pgkey="${k}" aria-label="${esc(l)}">${l}</button>`).join('')}</div><div id="pg-tools" class="pg-tools"></div><p id="pg-hint" class="small muted"></p><div class="row">${pgButton('暫停','pause','','secondary')}${pgButton('保存並返回大廳','leave','','soft')}${pgButton('操作說明','help','','quiet')}<span id="pg-score" class="chip"></span></div><div id="pg-status" class="sr-only" aria-live="polite"></div></section>`;}
function pgThumbs(){for(const box of $$('[data-pgthumb]')){const id=box.dataset.pgthumb;if(!pgThumbCache.has(id)){const cv=document.createElement('canvas');cv.width=800;cv.height=560;const meta=WQGames.find(g=>g.id===id);try{const game=new meta.Class({ctx:cv.getContext('2d'),meta,difficulty:1,seed:72,preview:true,tools(){},hint(){},announce(){},tone(){},complete(){},clock(){return 0},instrument(){},getData(){return null},putData(){}});game.draw();pgThumbCache.set(id,cv.toDataURL('image/webp',.76));}catch(e){console.error('thumbnail',id,e);}}const src=pgThumbCache.get(id);if(src){const im=document.createElement('img');im.src=src;im.alt='';im.loading='eager';im.width=800;im.height=560;box.append(im);}}}
function pgIntro(id){pgPause();const g=WQGames.find(g=>g.id===id),p=PG.catalog.find(g=>g.id===id);if(!g)return;$('#pg-dialog')?.remove();const d=document.createElement('dialog');d.id='pg-dialog';d.className='pg-dialog';const c=pgChild(),t=c.ticket,yes=pgAllow(id),left=PG.remainingDaily(c,pgDay());d.innerHTML=`<div class="pad"><div class="row between"><h2>${g.name}</h2>${pgButton('關閉','close-dialog','','quiet')}</div><p>${esc(g.guide)}</p>${yes?`<p class="small muted">挑戰程度：${['入門','標準','挑戰'][c.difficulty]} · 遊戲內分數不會產生學習金幣。</p>${adminUnlocks()?pgButton('免費開始測試','buy',`data-id="${id}" data-plan="short"`,'primary full'):t?.remainingMs>0?`${pgButton('使用餘下 '+pgTime(t.remainingMs)+' · 不扣幣','buy',`data-id="${id}" data-plan="short" ${left>0?'':'disabled'}`,'primary full')}`:`<div class="pg-plans">${['short','standard'].map(plan=>{const q=PG.plans[plan],can=activeChild().stars>=q.cost&&left>=q.ms;return pgButton(`${q.cost} 幣 · ${q.ms/1000} 秒`,'buy',`data-id="${id}" data-plan="${plan}" ${can?'':'disabled'}`,p.cost===q.cost?'primary':'secondary');}).join('')}</div>`}<p>今日餘下 ${pgTime(left)}。按確認只扣一次，然後自行按開始；時間內可重試及轉遊戲。</p>`:`<div class="notice">${!isLoggedIn()?'先登入本機帳戶。':c.override[id]==='blocked'?'這款遊戲已被家長暫停。':`累積 ${p.words} 個學習項目通過複習即可永久開放；現在有 ${PG.count(c)} 個。`}</div>${link('返回學習','kid','primary')}`}<p class="small muted">解鎖及存檔不會因為花星而失去。查看玩法不扣幣。</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function pgApi(meta,ctx,preview=false){return{ctx,meta,difficulty:pgChild().difficulty,seed:Math.floor(Math.random()*0xffffffff),preview,latency:0,
 tools(items){pgTools=items;pgRenderTools();},hint(t){pgHint=t;if($('#pg-hint'))$('#pg-hint').textContent=t;},announce(t){if($('#pg-status'))$('#pg-status').textContent=t;},tone:(...a)=>pgAudio.tone(...a),clock:()=>pgAudio.clock(),instrument:(...a)=>pgAudio.instrument(...a),
 complete(r){pgResult=r;pgPlaying=false;pgReason='round';pgAudio.pause();pgCheckpoint();pgOverlay();},getData:k=>pgFree?null:pgChild().extras[k],putData(k,v){if(pgFree)return false;pgChild().extras[k]=JSON.parse(JSON.stringify(v));return pgCheckpoint();},downloadJSON:pgDownload,importJSON:pgImport};}
function pgDownload(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function pgImport(callback){if(!pgPause())return;const owner=pgOwner,game=pgGame;const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{const f=i.files[0];if(!f||f.size>50000)return toast('作品檔須少於 50 KB。','bad');try{const value=JSON.parse(await f.text());if(owner!==pgOwner||game!==pgGame||owner!==accountId()+':'+activeChild().id)throw Error('孩子或遊戲已切換');callback(value);pgCheckpoint();pgGame?.draw();}catch{toast('作品檔格式不正確。','bad');}};i.click();}
async function pgBuy(id,plan){if(pgBusy||!pgAllow(id))return;const intentOwner=accountId()+':'+activeChild().id;pgBusy=true;pgError='';try{if(!pgPause())throw Error('尚有遊戲進度未能儲存；請先處理儲存問題。');arPause();arEngine=null;if(!await arAcquire())throw Error('另一個分頁正在玩遊戲；請先暫停它。');if(intentOwner!==accountId()+':'+activeChild().id)throw Error('孩子已切換，沒有扣幣。');arReadLatest();if(!pgAllow(id))throw Error('這款遊戲尚未開放。');pgFree=adminUnlocks();const g=WQGames.find(g=>g.id===id),cv=document.createElement('canvas');cv.width=800;cv.height=560;pgTools=[];pgResult=null;const candidate=new g.Class(pgApi(g,cv.getContext('2d'))),c=pgChild(),slot=id+'|'+c.difficulty;
 if(!pgFree&&c.saves[slot])PG.restore(candidate,c.saves[slot],WQCore.rng);candidate.draw(); // resource/restore preflight BEFORE charging
 const before=structuredClone(db);if(!pgFree){if(!c.ticket||c.ticket.remainingMs<=0){const result=PG.purchase(c,activeChild().stars,plan,pgDay(),uid('pg'),id);activeChild().stars=result.balance;}if(PG.remainingDaily(c,pgDay())<=0)throw Error('今日遊玩時間已用完；未用時間保留。');c.ticket.last=id;if(!save()){db=before;throw Error('未能儲存，這次沒有扣幣。');}}
 pgGame=candidate;pgMeta=g;pgSlot=slot;pgOwner=accountId()+':'+activeChild().id;pgPlaying=false;pgReason=candidate.done?'round':'ready';pgGame.toolbar?.();$('#pg-dialog')?.close();stopSpeech();pcStop();fgStopAudio();go('playground');render();
}catch(e){pgError=e.message;toast('未能開始：'+e.message,'bad');arDropLease();}finally{pgBusy=false;}}
function pgCheckpoint(){if(!pgGame||pgFree)return true;if(pgOwner!==accountId()+':'+activeChild().id)return false;try{const c=pgChild();c.saves[pgSlot]=PG.snapshot(pgGame);const score=Number(pgGame.score);if(Number.isFinite(score)&&score>=0)c.bests[pgSlot]=Math.max(c.bests[pgSlot]||0,score);if(!save())throw Error('尚未儲存；請勿關頁，先匯出備份。');return true;}catch(e){pgPlaying=false;pgReason='error';pgError=e.message;pgAudio.pause();cancelAnimationFrame(pgFrame);pgOverlay();return false;}}
function pgPause(){if(!pgGame)return true;pgPlaying=false;cancelAnimationFrame(pgFrame);pgAudio.pause();pgGame.keys.clear();if('charging' in pgGame)pgGame.charging=false;try{pgGame.pointer('cancel',{x:0,y:0});}catch{}pgReason=pgReason==='error'?'error':pgGame.done?'round':'paused';const ok=pgCheckpoint();arDropLease();pgOverlay();return ok;}
function pgOverlay(){const box=$('#pg-overlay');if(!box||!pgGame)return;box.hidden=pgPlaying;if(pgPlaying){box.replaceChildren();pgRenderTools();return;}let title='準備好了？',body='按開始才計時；暫停及看結果不扣時間。',actions=pgButton('開始','play','','primary');const c=pgChild(),left=c.ticket?.remainingMs||0;
 if(pgReason==='paused'){title='已暫停';body='進度和未用時間保留。';actions=pgButton('繼續','play','','primary');}
 if(pgGame.done){title=pgResult?.title||'這一關完成';body=pgResult?.text||'可繼續挑戰，或保存進度返回大廳。';actions=(pgGame._wqNext?pgButton('下一關 · 不扣幣','next','','primary'):'')+pgButton('重新挑戰 · 不扣幣','restart','','secondary');}
 if(!pgFree&&(left<=0||PG.remainingDaily(c,pgDay())<=0)){title=left<=0?'這次小休完成':'今日小休時間已用完';body='已保存目前關卡，下次可以接着玩。不會自動扣幣續玩。';actions=link('返回學習','kid','primary');}
 if(pgReason==='error'){title='遊戲已安全暫停';body=pgError||'未能保存，請先匯出資料。';actions=pgButton('重試儲存','retry-save','','primary');}
 box.innerHTML=`<div class="pg-overlaycard"><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row">${actions}${pgButton('返回大廳','leave','','soft')}</div><small>${pgFree?'Admin 測試不扣幣，亦不改孩子的棋盤':`餘下 ${pgTime(left)} · 已付款，不再扣幣`}</small></div>`;pgRenderTools();}
function pgRenderTools(){const box=$('#pg-tools');if(!box)return;box.innerHTML=pgTools.map(t=>`<button type="button" class="btn ${t.active?'primary':'soft'}" data-pgtool="${esc(t.id)}" ${typeof t.active==='boolean'?`aria-pressed="${t.active}"`:''} ${t.ariaLabel?`aria-label="${esc(t.ariaLabel)}"`:''} ${!pgPlaying||t.disabled?'disabled':''}>${esc(t.label)}</button>`).join('');$$('[data-pgkey]').forEach(b=>b.disabled=!pgPlaying);}
function pgAttach(){const cv=$('#pg-canvas');if(!cv||!pgGame)return;pgGame.c=cv.getContext('2d');pgGame.api.ctx=pgGame.c;pgPlaying=false;pgGame.draw();pgOverlay();pgRenderTools();$('#pg-hint').textContent=pgHint;let pointer=null;const point=e=>{const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*800/r.width,y:(e.clientY-r.top)*560/r.height};};
 cv.addEventListener('pointerdown',e=>{if(!pgPlaying||pointer!==null)return;pointer=e.pointerId;cv.setPointerCapture(pointer);e.preventDefault();pgGame.pointer('down',point(e));});cv.addEventListener('pointermove',e=>{if(pgPlaying&&(pointer===null||pointer===e.pointerId))pgGame.pointer('move',point(e));});for(const ev of ['pointerup','pointercancel','lostpointercapture'])cv.addEventListener(ev,e=>{if(pointer!==e.pointerId)return;pointer=null;if(pgPlaying)pgGame.pointer(ev==='pointerup'?'up':'cancel',point(e));});
 $$('[data-pgkey]').forEach(b=>{b.addEventListener('pointerdown',e=>{if(!pgPlaying)return;e.preventDefault();b.setPointerCapture(e.pointerId);pgGame.key(b.dataset.pgkey,true);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>pgGame?.key(b.dataset.pgkey,false));});}
async function pgPlay(){if(pgBusy||!pgGame||pgGame.done)return;if(pgOwner!==accountId()+':'+activeChild().id||(pgFree&&!adminUnlocks())){pgGame=null;go('game');render();return;}pgBusy=true;try{if(!await arAcquire())throw Error('另一個分頁正在玩，請先暫停。');const remote=JSON.parse(localStorage.getItem(dbKey())||'null');if(remote&&remote.writeRevision>db.writeRevision)throw Error('另一分頁更新了資料，請重開頁面讀取，勿覆蓋新紀錄。');if(!pgFree&&(pgChild().ticket?.remainingMs<=0||PG.remainingDaily(pgChild(),pgDay())<=0))return pgOverlay();if(!pgFree&&!pgAllow(pgMeta.id))throw Error('這款遊戲已暫停開放。');if(!pgCheckpoint())return;pgPlaying=true;pgReason='';pgGame.keys.clear();pgLast=performance.now();pgAcc=0;pgOverlay();$('#pg-canvas')?.focus({preventScroll:true});await pgAudio.unlock();if(!pgPlaying)return;pgLast=performance.now();pgGame.onResume?.();cancelAnimationFrame(pgFrame);pgFrame=requestAnimationFrame(pgTick);}catch(e){pgError=e.message;pgReason='error';pgOverlay();arDropLease();}finally{pgBusy=false;}}
function pgTick(now){if(!pgPlaying||!pgGame||lastRoute!=='playground')return;const elapsed=Math.max(0,now-pgLast);pgLast=now;if(document.hidden){pgPause();return;}try{const ms=pgFree?elapsed:PG.consume(pgChild(),pgDay(),elapsed);let left=Math.min(ms/1000,.25);while(left>1e-7&&pgPlaying){const h=Math.min(1/60,left);pgGame.tick(h);left-=h;}pgGame.draw();$('#pg-clock').textContent=pgFree?'測試不限時':pgTime(pgChild().ticket.remainingMs);$('#pg-score').textContent=`${pgGame.stat||''} · ${Math.round(pgGame.score||0)} 分`;pgAcc+=elapsed;if(!pgFree&&(pgChild().ticket.remainingMs<=0||PG.remainingDaily(pgChild(),pgDay())<=0)){pgPause();return;}if(pgAcc>=600){pgAcc=0;if(!pgCheckpoint())return;}if(pgPlaying)pgFrame=requestAnimationFrame(pgTick);}catch(e){pgPlaying=false;pgError=e.message;pgReason='error';pgAudio.pause();pgCheckpoint();pgOverlay();}}
function pgNext(){if(!pgGame?._wqNext)return;pgGame.done=false;pgGame._wqNext=false;switch(pgMeta.id){case'honey-delivery':case'rolling-block':case'juice-lines':case'color-workshop':pgGame.level++;pgGame.load();break;case'little-engineer':pgGame.level++;pgGame.loadSim();pgGame.toolbar();break;case'number-garden':break;default:pgGame.done=true;return;}pgResult=null;pgCheckpoint();pgPlay();}
function pgRestart(){if(!pgGame)return;const cv=$('#pg-canvas');pgGame=new pgMeta.Class(pgApi(pgMeta,cv.getContext('2d')));pgResult=null;pgCheckpoint();pgPlay();}
/* Host-closure audio adapter. A gesture unlocks the context BEFORE play is committed.
 * Both buses honour the global mute. Zero volume means no scheduled nodes.
 * No wall-clock sequencer: game simulation schedules music, so pause is immediate.
 */
const pgAudio={ctx:null,nodes:new Set(),master:null,musicMaster:null,epoch:0,lastError:'',sample:false,
 async unlock(){const request=++this.epoch;try{if(!this.ctx||this.ctx.state==='closed'){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){this.lastError='此瀏覽器沒有 Web Audio';return false;}this.ctx=new AC();this.master=this.ctx.createGain();this.musicMaster=this.ctx.createGain();this.master.connect(this.ctx.destination);this.musicMaster.connect(this.ctx.destination);}this.mute();if(this.ctx.state==='suspended')await this.ctx.resume();if(request!==this.epoch)return false;this.lastError='';return this.ctx.state==='running';}catch(e){this.lastError=String(e.message||e);toast('未能啟動音效；可無聲遊玩，或按「試音」重試。');return false;}},
 volume(kind){const key=kind==='music'?'arcadeMusicVolume':'arcadeSfxVolume',n=db?.settings?.[key];return Math.max(0,Math.min(100,Number.isFinite(n)?n:kind==='music'?35:60))/100;},
 tone(f=600,d=.1,wave='sine',vol=.1,at=null,kind='sfx'){if(!this.ctx||this.ctx.state!=='running'||!sfxEnabled()||!pgPlaying&&!this.sample||this.volume(kind)===0||this.nodes.size>=64)return;const t=Math.max(this.ctx.currentTime+.001,at??this.ctx.currentTime+.003),duration=Math.max(.025,Math.min(.5,Number.isFinite(d)?d:.1));const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=['sine','triangle','square','sawtooth'].includes(wave)?wave:'sine';o.frequency.value=Math.max(30,Math.min(6000,Number.isFinite(f)?f:600));g.gain.setValueAtTime(.00001,t);g.gain.exponentialRampToValueAtTime(Math.max(.00002,Math.min(.22,Number.isFinite(vol)?vol:.1)),t+.007);g.gain.exponentialRampToValueAtTime(.00001,t+duration);o.connect(g);g.connect(kind==='music'?this.musicMaster:this.master);o.start(t);o.stop(t+duration+.025);this.nodes.add(o);o.onended=()=>{this.nodes.delete(o);try{o.disconnect();g.disconnect();}catch{}};},
 drum(kind,at){this.tone(kind===0?95:kind===1?230:1150,kind===0?.18:.045,kind===0?'sine':'triangle',kind===0?.15:.06,at);},
 instrument(track,step,at){if(track<3)this.drum(track,at);else this.tone((track===3?[130.81,146.83,164.81,174.61]:[523.25,587.33,659.25,783.99])[step%4],.22,'triangle',.07,at);},
 pause(){this.epoch++;this.sample=false;for(const n of this.nodes)try{n.stop();}catch{}this.nodes.clear();if(this.ctx?.state==='running')this.ctx.suspend().catch(()=>{});},
 clock(){return this.ctx?this.ctx.currentTime:performance.now()/1000;},
 mute(){if(!this.ctx)return;const enabled=sfxEnabled(),t=this.ctx.currentTime;for(const[k,b]of [['sfx',this.master],['music',this.musicMaster]])if(b){b.gain.cancelScheduledValues(0);b.gain.value=enabled?this.volume(k)*.8:0;}},
 async test(){if(!sfxEnabled()){toast('目前總聲效已關閉，先按頁首聲效開關。');return;}if(!await this.unlock())return;const epoch=this.epoch;this.sample=true;this.tone(523.25,.14,'triangle',.1);this.tone(659.25,.14,'triangle',.1,this.ctx.currentTime+.15);setTimeout(()=>{if(epoch!==this.epoch)return;this.sample=false;if(!pgPlaying)this.pause();},420);}
};

// Learning signals: no fabricated back-fill from older ambiguous attempt history.
function pgHinted(){return !!currentItem()&&pgChild().hints.includes(currentItem().id);}
const pgPriorHelp=showHelp;showHelp=function(){if(isLoggedIn()&&currentItem()&&currentWord()){const c=pgChild();if(!c.hints.includes(currentItem().id))c.hints.push(currentItem().id);c.hints=c.hints.slice(-2000);v24Expose([currentWord().en]);save();}return pgPriorHelp();};
const pgPriorBody=taskBody;taskBody=function(it,w){if(isLoggedIn()&&['study','meaning','listenChoice','missing'].includes(it.type)){PG.reveal(pgChild(),w.en,Date.now());save();}return pgPriorBody(it,w);};
const pgPriorRecord=recordAttempt;recordAttempt=function(w,type,correct,answer,expected,origin,detail){const hinted=pgHinted()||v24RecentExposure(w,type)||(v24Policy().grading==='practice'&&detail?.capitalization===false);pgPriorRecord(w,type,correct,answer,expected,origin,detail);if(hinted)db.attempts.at(-1).assisted=true;const c=pgChild();if(w.kind==='sentence')PG.sentenceAttempt(c,{word:w.en,correct:correct&&detail?.capitalization!==false,hinted,time:Date.now()});else (w.kind==='phrase'?PG.phraseAttempt:PG.attempt)(c,{word:w.en,type:['cloze','sentence'].includes(type)?'spell':type,correct,hinted,time:Date.now()});if(pgRoot().mode==='balanced'&&db.session?.mode==='daily'&&currentItem()){if(!correct&&!db.session.feedback?.technical){const pending=c.pending,seen=new Set();for(const[k,p]of Object.entries(pending)){const word=PG.key(p.en);if(seen.has(word))delete pending[k];else seen.add(word);}if(!seen.has(PG.key(w.en))&&Object.keys(pending).length<10000)pending[currentItem().id]={en:w.en,wordId:w.id};}}};
