  x.settings=structuredClone(db.settings);x.playgroundV22=structuredClone(db.playgroundV22||PG.initial());x.arcade=structuredClone(db.arcade);x.dailyLedger=structuredClone(db.dailyLedger||{});
  // Keep rewards and course progress together; a restored incomplete course must not be farmed for stars.
