// Ephemeral parent re-authentication, bound to account+child and invalidated on switch/logout.
function v23ParentAllowed(){return (isTestAdmin()&&WQ_TEST_MODE)||(v23ParentOwner===v23Owner()&&performance.now()<v23ParentUntil);}
function v23Gate(){return `<section class="card pad" style="max-width:620px;margin:24px auto"><h1>家長確認</h1><p>修改家庭、遊戲或備份設定前，請輸入此本機帳戶的密碼／舊 PIN。</p><label for="v23-parent-password">家長密碼</label><input id="v23-parent-password" class="input" type="password" maxlength="128" autocomplete="current-password"><p><button class="btn primary" data-v23="parent-unlock">確認家長身份</button> ${link('返回孩子首頁','kid','soft')}</p><p id="v23-parent-error" role="status"></p><p class="small muted">確認只維持 5 分鐘，切換孩子即失效。這是本機操作保護，不是雲端安全登入。</p></section>`;}
const v23ParentRoutes=new Set(['parent','children','settings','game-settings','range-new','offline','report','admin']);
const v23ParentActions=new Set(['add-child','delete-child','save-settings','reset-all','restore-data','export-data','export-raw','save-range','remove-range','delete-range','save-uploaded-audio','save-uploaded-image','save-media','import-media','delete-media']);
async function v23Unlock(){
 if(authBusy)return;const owner=v23Owner(),pw=$('#v23-parent-password')?.value||'',e=$('#v23-parent-error');
 if(performance.now()<v23AuthBlockedUntil){if(e)e.textContent='嘗試太多，請稍後再試。';return;}authBusy=true;
 try{if(!await WQAuth.verify(pw,currentAccount())){v23AuthFailures++;if(v23AuthFailures>=5)v23AuthBlockedUntil=performance.now()+30000;if(e)e.textContent='密碼不正確。';return;}if(owner!==v23Owner())return;v23AuthFailures=0;v23ParentOwner=owner;v23ParentUntil=performance.now()+300000;render();}
 catch(err){if(e)e.textContent=err.message;}finally{authBusy=false;}
}
async function v23ChangePassword(){
 if(authBusy||!v23ParentAllowed()||!v23HasLease())return;
 const pw=$('#v23-new-password')?.value||'',again=$('#v23-confirm-password')?.value||'',owner=v23Owner(),prior={...currentAccount()};
 if(pw.length<8||pw.length>128||pw!==again){toast('新密碼須有 8–128 字，兩次輸入要相同。','bad');return;}
 authBusy=true;
 try{
  const salt=WQAuth.salt(),pinHash=await WQAuth.hash(pw,salt);
  if(owner!==v23Owner()||!v23ParentAllowed())throw Error('身份改變或授權到期，密碼未改動。');
  await navigator.locks.request(WQ_TEST_MODE?'wordquest-v29-test-registry':'wordquest-account-registry',async()=>{
   if(owner!==v23Owner()||!v23ParentAllowed())throw Error('家長授權已失效。');
   const accounts=readAccounts(),current=accounts.find(a=>a.id===prior.id);
   if(!current||current.pinHash!==prior.pinHash||current.salt!==prior.salt)throw Error('帳戶已由另一分頁更新，請重新登入。');
   writeAccounts(accounts.map(a=>a.id===prior.id?{...a,salt,pinHash}:a));
  });
  v23ParentUntil=0;toast('密碼已更改。下次家長確認請使用新密碼。');render();
 }catch(e){toast('密碼未更改：'+e.message,'bad');}finally{authBusy=false;}
}
function v23PasswordPanel(){
 if(isTestAdmin())return '';
 return `<section class="card pad" id="v23-password-panel"><h2>更改家長密碼</h2><p>舊帳戶的 PIN 可以繼續登入，但四位數容易被猜中。請在這裏改為 8–128 字的密碼，不要與其他網站共用。</p><div class="grid2"><label>新密碼<input id="v23-new-password" class="input" type="password" maxlength="128" autocomplete="new-password"></label><label>再次輸入<input id="v23-confirm-password" class="input" type="password" maxlength="128" autocomplete="new-password"></label></div><button class="btn primary" data-v23="change-password">更改密碼</button></section>`;
}
