  if(a==='reset-game')void(async()=>{if(!await arAcquire())return;if(!confirm('只重設這款遊戲此難度的棋盤？金幣及其他遊戲不變。'))return;const before=structuredClone(db),c=pgChild();delete c.saves[b.dataset.slot];delete c.quarantine?.[b.dataset.slot];if(!save()){db=before;return;}pgGame=null;pgIntro(b.dataset.game);})();
