  const warning=blocked?(protectedDb?'已找到本機錢包保障紀錄。恢復教材與作答紀錄，保留最新已保存金幣及用時。':'原資料已損壞，沒有可核對的錢包保障紀錄。只恢復教材及學習成果；金幣及未用遊戲時間重設為 0，今天暫停遊戲。原損壞檔會保留。'): '還原教材及學習紀錄；目前金幣、已購時間、用時及家長規則不會倒退。';
  if(!confirm(warning+'\n這份備份：'+inspected.summaries.children+' 位孩子、'+inspected.summaries.ranges+' 份範圍、'+inspected.summaries.items+' 個學習項目、'+inspected.summaries.attempts+' 次作答。'+(inspected.integrity==='verified'?' 已通過完整性校驗。':' 舊格式沒有校驗碼，已檢查資料結構。')+' 繼續？'))return;
  if(protectedDb)x=v24MergeProtected(x,protectedDb,blocked);
  else {for(const c of x.children){c.stars=0;const p=PG.get(x.playgroundV22,c.id);p.ticket=null;p.sessions=[];PG.day(p,today()).usedMs=p.limit*60000;}if(x.arcade)x.arcade.active={};x.arcadeV28=window.WQArcade28.initial(x.children);for(const c of Object.values(x.arcadeV28.children))c.paused=true;x.writeRevision=0;}
  x.writeRevision=(x.writeRevision||0)+1;if(!Number.isSafeInteger(x.writeRevision))throw Error('資料版本超限');
  x=validateDb(x);const prepared=JSON.stringify(x);
  if(owner!==v23Owner()||!v23ParentAllowed()||!v23HasLease()||localStorage.getItem(key)!==original)throw Error('還原條件已改變');
