 for(const t of items){wanted.add(t.id);let b=byId.get(t.id);if(!b){b=document.createElement('button');b.type='button';b.dataset.a28tool=t.id;box.append(b);}b.className='btn '+(t.active?'primary':'soft');const label=t.id==='reset'?'重開本關（用一次機會）':t.label;if(b.textContent!==label)b.textContent=label;b.disabled=!pgPlaying||!!t.disabled;if(typeof t.active==='boolean')b.setAttribute('aria-pressed',String(t.active));else b.removeAttribute('aria-pressed');if(t.ariaLabel)b.setAttribute('aria-label',t.ariaLabel);else b.removeAttribute('aria-label');}
 for(const b of [...box.children])if(!wanted.has(b.dataset.a28tool))b.remove();for(const b of $$('.a28-touch-key'))b.disabled=!pgPlaying;
