 if(k==='action'&&pgGame&&'charging'in pgGame)pgGame.charging=false;
 if(pgGame){pgGame.keys.delete(k);if(WQR2.ids.includes(pgGame.meta.id)&&['up','action'].includes(k)){if('jumpHeld' in pgGame)pgGame.jumpHeld=pgGame.keys.has('up')||pgGame.keys.has('action');if('jumpBuffer' in pgGame&&!pgGame.jumpHeld)pgGame.jumpBuffer=0;if('spike' in pgGame)pgGame.spike=0;}}
