  const key=b.dataset.a28key;
  b.addEventListener('pointerdown',e=>{if(!pgPlaying)return;e.preventDefault();b.setPointerCapture(e.pointerId);a28Input(key,true,'p'+e.pointerId);b.classList.add('held');});
