async function a28Refund(){if(a28Busy||!a28CanWrite())return;const r=a28Run();if(!r||!confirm('取消完全未開始的一局，退回一個金幣？'))return;a28Busy=true;const before=structuredClone(db);try{arReadLatest();activeChild().stars=COIN28.refund(a28Child(),activeChild().stars,r.id);if(!save()){db=before;throw Error('未能儲存，未有退幣。');}pgGame=null;pgPlaying=false;go('game');render();}catch(e){toast(e.message,'bad');}finally{a28Busy=false;}}
