 if(!a28CanWrite())return 0;const c=a28Child(),result=COIN28.task(c,activeChild().stars,{key,day:today(),startedAt:Math.max(0,Date.parse(startedAt)||0),completedAt:Date.now(),valid});activeChild().stars=result.balance;
 a28LastAward={...result,owner:a28Own(),sessionId:db.session?.id};return result.award;
